BOARD_ORIGIN = 100.0

MEDIA_REF = re.compile(r"!\[[^\]]*\]\(media:([0-9a-fA-F-]{36})\)")
CARD_REF = re.compile(r"(?<!!)\[(?:\\.|[^\[\]\\])*\]\(card:([0-9a-fA-F-]{36})\)")
MAX_FILE_SIZE = 2 * 1024 * 1024  # 2MB
MAX_BACKUP_FILES = 3


def compute_file_hash(content: bytes) -> str:
    return hashlib.sha256(content).hexdigest()


def find_code_blocks(body: str) -> list[dict[str, Any]]:
    """以動態長度圍欄解析 Markdown 代碼塊，支援任意長度反引號或波浪號。"""
    pattern = re.compile(
r"^(?P<indent>[ \t]*)(?P<fence>`{3,}|~{3,})(?P<info>[^\n]*)\n(?:(?P<code>[\s\S]*?)\r?\n)?(?P=indent)(?P=fence)[ \t]*\r?$",
        re.MULTILINE,
    )
    blocks = []
    for m in pattern.finditer(body):
        code_val = m.group("code") or ""
        blocks.append({
            "start": m.start(),
            "end": m.end(),
            "fence": m.group("fence"),
            "info": m.group("info").strip(),
            "code": code_val,
        })
    return blocks


def block_label_name(block: dict[str, Any]) -> str:
    """代碼塊標籤的檔名（```tsx:Board.tsx → board.tsx）；沒有「:」標籤則回傳空字串。"""
    info = block["info"]
    if ":" not in info:
        return ""
    return Path(info.split(":", 1)[1].strip()).name.lower()


def select_block(blocks: list[dict[str, Any]], target_filename: str) -> dict[str, Any]:
    """標籤檔名完全相等優先；唯一且未標檔名的代碼塊才可使用；其餘一律報錯，不猜。"""
    want = target_filename.lower()
    matched = [b for b in blocks if block_label_name(b) == want]
    if len(matched) == 1:
        return matched[0]
    if len(matched) > 1:
        raise AppError(ErrorCode.VALIDATION_ERROR, f"有多個代碼塊都標註為「{target_filename}」，無法判定")
    if len(blocks) == 1 and not block_label_name(blocks[0]):
        return blocks[0]
    labels = [b["info"] or "（未標記）" for b in blocks]
    raise AppError(
        ErrorCode.VALIDATION_ERROR,
        f"找不到標註為「{target_filename}」的代碼塊；請在代碼塊標籤註明檔名（例如 python:{target_filename}）",
        {"available_labels": labels},
    )


def extract_target_code(body: str, target_filename: str) -> tuple[str, bool]:
    """從卡片提取代碼：優先匹配標籤包含目標檔名的代碼塊；無代碼塊或空代碼塊則拒絕寫入。"""
    blocks = find_code_blocks(body)
    if not blocks:
        raise AppError(ErrorCode.VALIDATION_ERROR, "卡片內沒有找到 Markdown 代碼塊，拒絕覆寫檔案")

    chosen = select_block(blocks, target_filename)

    code = chosen["code"]
    if not code.strip():
        raise AppError(ErrorCode.VALIDATION_ERROR, "選定的代碼塊為空，拒絕寫入空檔案")
    return code, True


def inject_target_code(original_body: str, target_filename: str, new_code: str) -> str:
    """將檔案內容安全注入卡片中匹配的代碼塊，動態擴增圍欄長度避免破壞 Markdown 結構。"""
    blocks = find_code_blocks(original_body)
    if not blocks:
        # 原卡片無代碼塊：保留原內文，把檔案內容以帶檔名標籤的代碼塊附在最後，不丟失任何原有文字
        backticks = "```"
        while backticks in new_code:
            backticks += "`"
        lang = Path(target_filename).suffix.lstrip(".") or "text"
        sep = "\n\n" if original_body.strip() else ""
        return f"{original_body.rstrip()}{sep}{backticks}{lang}:{target_filename}\n{new_code}\n{backticks}\n"

    chosen = select_block(blocks, target_filename)

    fence_char = chosen["fence"][0]
    max_consecutive = 0
    cur_count = 0
    for ch in new_code:
        if ch == fence_char:
            cur_count += 1
            if cur_count > max_consecutive:
                max_consecutive = cur_count
        else:
            cur_count = 0

    needed_len = max(len(chosen["fence"]), max_consecutive + 1, 3)
    new_fence = fence_char * needed_len
    new_block = f"{new_fence}{chosen['info']}\n{new_code}\n{new_fence}"
    return original_body[:chosen["start"]] + new_block + original_body[chosen["end"]:]


# 系統目錄黑名單：這是防手滑，不是安全邊界；真正的邊界是伺服器只綁 127.0.0.1、CORS 設白名單
_BLOCKED_DIRS: list[Path] = [
    Path(p) for p in ("/etc", "/proc", "/sys", "/dev", "/boot", "/bin", "/sbin", "/usr", "/lib", "/lib64")
]
for _env in ("SystemRoot", "ProgramFiles", "ProgramFiles(x86)", "ProgramData"):
    _val = os.environ.get(_env)
    if _val:
        _BLOCKED_DIRS.append(Path(_val))


def resolve_safe_path(raw_path: str) -> Path:
    """解析並驗證路徑：必須是絕對路徑（可用 ~）、上層目錄已存在、不在系統目錄、不是磁碟根目錄下的檔案。"""
    try:
        expanded = Path(os.path.expanduser(raw_path.strip()))
        # 先判斷再 resolve：resolve 會把相對路徑以伺服器工作目錄補成絕對路徑，之後再檢查就永遠為真
        if not expanded.is_absolute():
            raise AppError(
                ErrorCode.VALIDATION_ERROR,
                "檔案路徑必須是絕對路徑（例如 C:\\project\\app.py，或 ~/project/app.py）",
            )
        p = expanded.resolve()
    except (OSError, ValueError, RuntimeError) as e:
        raise AppError(ErrorCode.VALIDATION_ERROR, f"檔案路徑無效：{e}")
    if p.is_dir():
        raise AppError(ErrorCode.VALIDATION_ERROR, "指定路徑為目錄，必須是檔案路徑")
    if not p.parent.is_dir():
        raise AppError(ErrorCode.VALIDATION_ERROR, f"目標檔案的上層目錄不存在：{p.parent}")
    if p.parent == Path(p.anchor):
        raise AppError(ErrorCode.VALIDATION_ERROR, "禁止綁定磁碟根目錄下的檔案")
    if any(p == d or d in p.parents for d in _BLOCKED_DIRS):
        raise AppError(ErrorCode.VALIDATION_ERROR, "禁止綁定系統目錄內的檔案")
    return p


def list_backups(target: Path) -> list[Path]:
    """列出此檔案的備份，新到舊。
    依檔名內的時間戳排序（不用 mtime：copy2 會保留來源檔的 mtime）；
    不用 glob（檔名含 [ ] 會被當成萬用字元）。"""
    backup_dir = target.parent / "cardboard_backups"
    if not backup_dir.is_dir():
        return []
    pat = re.compile(rf"^{re.escape(target.name)}\.\d{{8}}_\d{{6}}_\d{{6}}\.bak$")
    found = [f for f in backup_dir.iterdir() if pat.match(f.name) and f.is_file()]
    return sorted(found, key=lambda f: f.name, reverse=True)


def rotate_backups(target: Path) -> Path:
    """在 cardboard_backups/ 建立帶微秒時間戳的備份，最多保留 MAX_BACKUP_FILES 份。"""
    backup_dir = target.parent / "cardboard_backups"
    backup_dir.mkdir(exist_ok=True)
    ts = datetime.now(timezone.utc).strftime("%Y%m%d_%H%M%S_%f")
    backup_file = backup_dir / f"{target.name}.{ts}.bak"
    shutil.copy2(target, backup_file)
    for old_bak in list_backups(target)[MAX_BACKUP_FILES:]:
        try:
            old_bak.unlink()  # 清舊備份失敗只會多留檔案，不影響本次操作
        except OSError:
            pass
    return backup_file


def parse_backup_time(bak_name: str) -> str:
    """從檔名 target.YYYYMMDD_HHMMSS_ffffff.bak 解析出可讀時間。"""
    try:
        parts = bak_name.rsplit(".", 2)
        if len(parts) >= 3:
            ts_str = parts[-2]
            dt = datetime.strptime(ts_str, "%Y%m%d_%H%M%S_%f")
            return dt.strftime("%Y-%m-%d %H:%M:%S")
    except Exception:
        pass
    return "未知時間"


def get_latest_backup(target: Path) -> Optional[Path]:
    baks = list_backups(target)
    return baks[0] if baks else None


def decode_text_file(raw: bytes) -> str:
    """檔案位元組 → 卡片用文字：去 BOM、CRLF 轉 LF、去掉結尾的一個換行（寫入時再依原檔補回），讓讀入與寫出對稱。"""
    text = raw[3:].decode("utf-8") if raw.startswith(b"\xef\xbb\xbf") else raw.decode("utf-8")
    text = text.replace("\r\n", "\n")
    return text[:-1] if text.endswith("\n") else text


def save_file_state(conn: sqlite3.Connection, card_id: str, file_hash: Optional[str], file_mtime: float) -> None:
    conn.execute(
        "UPDATE cards SET file_hash = ?, file_mtime = ? WHERE id = ?",
        (file_hash, file_mtime, card_id),
    )


def apply_file_to_card(
    conn: sqlite3.Connection,
    card_id: str,
    base_updated_at: str,
    new_body: str,
    new_hash: str,
    new_mtime: float,
) -> None:
    """把檔案內容寫回卡片；只有卡片版本沒變才更新。
    否則代表檔案 I/O 期間 Editor 已自動儲存，丟出 STALE_VERSION，而不是蓋掉它。"""
    cur = conn.execute(
        """UPDATE cards SET body = ?, file_hash = ?, file_mtime = ?, updated_at = ?
           WHERE id = ? AND updated_at = ?""",
        (new_body, new_hash, new_mtime, utc_now(), card_id, base_updated_at),
    )
    if cur.rowcount == 0:
        raise AppError(
            ErrorCode.STALE_VERSION,
            "卡片在處理檔案期間被修改，請重新載入後再試",
            {"current": card_detail(conn, card_id)},
        )


def parse_sources(raw: Optional[str]) -> list[str]:
    """cards.sources 存 JSON 陣列字串；空值視為沒有出處。內容損壞時讓 json 例外往上拋，不默默當成空。"""
    return json.loads(raw) if raw else []

def media_refs(body: str) -> list[str]:
    return list(dict.fromkeys(m.lower() for m in MEDIA_REF.findall(body)))


def missing_media(conn: sqlite3.Connection, body: str) -> list[str]:
    ids = media_refs(body)
    if not ids:
        return []
    marks = ",".join("?" * len(ids))
    found = {r["id"] for r in conn.execute(f"SELECT id FROM media WHERE id IN ({marks})", ids)}
    return [i for i in ids if i not in found]


def card_refs(body: str) -> list[str]:
    return list(dict.fromkeys(m.lower() for m in CARD_REF.findall(body)))


def missing_cards(conn: sqlite3.Connection, body: str) -> list[str]:
    ids = card_refs(body)
    if not ids:
        return []
    marks = ",".join("?" * len(ids))
    found = {r["id"] for r in conn.execute(f"SELECT id FROM cards WHERE id IN ({marks})", ids)}
    return [i for i in ids if i not in found]


def card_detail(conn: sqlite3.Connection, card_id: str) -> dict[str, Any]:
    row = conn.execute("SELECT * FROM cards WHERE id = ?", (card_id,)).fetchone()
    if row is None:
        raise AppError(ErrorCode.NOT_FOUND, "卡片不存在", {"card_id": card_id})
    tag_rows = conn.execute(
        """SELECT t.id, t.name, t.axis, t.facet, t.definition, t.parent_id FROM tags t
           JOIN card_tags ct ON ct.tag_id = t.id WHERE ct.card_id = ? ORDER BY t.axis, t.name""",
        (card_id,),
    ).fetchall()
    tag_ids = [t["id"] for t in tag_rows]
    by_tag: dict[str, list[str]] = {}
    if tag_ids:
        marks = ",".join("?" * len(tag_ids))
        for ar in conn.execute(
            f"SELECT tag_id, alias FROM tag_aliases WHERE tag_id IN ({marks}) ORDER BY alias", tag_ids
        ):
            by_tag.setdefault(ar["tag_id"], []).append(ar["alias"])
    tags = [
        {
            "id": t["id"],
            "name": t["name"],
            "axis": t["axis"],
            "facet": t["facet"],
            "definition": t["definition"] or "",
            "parent_id": t["parent_id"],
            "aliases": by_tag.get(t["id"], []),
        }
        for t in tag_rows
    ]
    link_rows = conn.execute(
        """SELECT c.id, c.title, l.source_id, l.target_id, l.relation_type, l.status, l.reason
           FROM links l
           JOIN cards c ON (l.source_id = ? AND c.id = l.target_id)
                        OR (l.target_id = ? AND c.id = l.source_id)
           ORDER BY c.title, l.relation_type""",
        (card_id, card_id),
    ).fetchall()
    links = [
        {
            "id": r["id"],
            "title": r["title"],
            "source_id": r["source_id"],
            "target_id": r["target_id"],
            "direction": "outgoing" if r["source_id"] == card_id else "incoming",
            "relation_type": r["relation_type"],
            "status": r["status"],
            "reason": r["reason"] or "",
        }
        for r in link_rows
    ]
    boards = conn.execute(
        """SELECT b.id, b.name FROM boards b JOIN board_cards bc ON bc.board_id = b.id
           WHERE bc.card_id = ? ORDER BY b.name""",
        (card_id,),
    ).fetchall()
    missing_m = missing_media(conn, row["body"])
    missing_c = missing_cards(conn, row["body"])
    warnings = []
    if missing_m:
        warnings.append({"code": "MISSING_MEDIA", "ids": missing_m})
    if missing_c:
        warnings.append({"code": "MISSING_CARD", "ids": missing_c})
    row_dict = dict(row)
    return {
        **row_dict,
        "file_path": row_dict.get("file_path") or None,
        "file_hash": row_dict.get("file_hash") or None,
        "file_mtime": row_dict.get("file_mtime"),
        "sources": parse_sources(row_dict.get("sources")),
        "tags": tags,
        "links": links,
        "boards": [dict(r) for r in boards],
        "warnings": warnings,
    }


def _impact(conn: sqlite3.Connection, card_id: str) -> dict[str, Any]:
    if conn.execute("SELECT 1 FROM cards WHERE id = ?", (card_id,)).fetchone() is None:
        raise AppError(ErrorCode.NOT_FOUND, "卡片不存在", {"card_id": card_id})
    boards = conn.execute(
        """SELECT b.name FROM boards b JOIN board_cards bc ON bc.board_id = b.id
           WHERE bc.card_id = ? ORDER BY b.name""",
        (card_id,),
    ).fetchall()
    links = conn.execute(
        "SELECT COUNT(*) AS n FROM links WHERE source_id = ? OR target_id = ?", (card_id, card_id)
    ).fetchone()["n"]
    return {"board_count": len(boards), "board_names": [b["name"] for b in boards], "link_count": links}


def like_pattern(q: str) -> str:
    esc = q.replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_")
    return f"%{esc}%"


def _snippet(body: str, q: Optional[str]) -> str:
    if q:
        idx = body.lower().find(q.lower())
        if idx >= 0:
            start = max(0, idx - 40)
            return ("…" if start else "") + body[start : idx + 120]
    return body[:160]


@router.post("/cards", status_code=201)
def create_card(payload: CardCreate, request: Request):
    with session(request, write=True) as conn:
        for tid in payload.tag_ids:
            if conn.execute("SELECT 1 FROM tags WHERE id = ?", (tid,)).fetchone() is None:
                raise AppError(ErrorCode.NOT_FOUND, "標籤不存在", {"tag_id": tid})
        cid, now = new_id(), utc_now()
        conn.execute(
            """INSERT INTO cards (id, title, body, card_type, curation_status, created_at, updated_at)
               VALUES (?, ?, ?, ?, ?, ?, ?)""",
            (cid, payload.title, payload.body, payload.card_type.value, payload.curation_status.value, now, now),
        )
        conn.executemany(
            "INSERT OR IGNORE INTO card_tags (card_id, tag_id) VALUES (?, ?)",
            [(cid, tid) for tid in payload.tag_ids],
        )
        return card_detail(conn, cid)


