@router.post("/cards/{card_id}/file/restore")
def restore_card_file_backup(card_id: str, request: Request, payload: Optional[CardFileRestoreRequest] = None):
    """還原指定或最新一份備份檔，還原前自動留存當前檔案快照以確保雙向可逆。"""
    with session(request, write=False) as conn:
        row = conn.execute("SELECT * FROM cards WHERE id = ?", (card_id,)).fetchone()
        if row is None:
            raise AppError(ErrorCode.NOT_FOUND, "卡片不存在", {"card_id": card_id})
        raw_path = row["file_path"]
        if not raw_path:
            raise AppError(ErrorCode.VALIDATION_ERROR, "此卡片尚未綁定本機檔案路徑")

    target = resolve_safe_path(raw_path)
    chosen_bak: Optional[Path] = None
    if payload and payload.backup_filename:
        candidate = target.parent / "cardboard_backups" / Path(payload.backup_filename).name
        if candidate.is_file():
            chosen_bak = candidate
    if not chosen_bak:
        chosen_bak = get_latest_backup(target)

    if not chosen_bak or not chosen_bak.is_file():
        raise AppError(ErrorCode.NOT_FOUND, "找不到可用的上一版備份檔案")

    temp_file_path: Optional[Path] = None
    try:
        backup_bytes = chosen_bak.read_bytes()
        # 原因：卡片沒有歷史，連卡片一起覆蓋會讓「已存入資料庫、尚未寫入檔案」的內文永久消失；還原因此只動檔案，
        # 也不再解析代碼塊，多代碼塊的卡片一樣能還原檔案。
        if target.exists():
            rotate_backups(target)

        with tempfile.NamedTemporaryFile("wb", dir=str(target.parent), delete=False) as tf:
            temp_file_path = Path(tf.name)
            tf.write(backup_bytes)
            tf.flush()
            os.fsync(tf.fileno())

        if target.exists():
            try:
                shutil.copymode(target, temp_file_path)
            except OSError:
                pass
        os.replace(temp_file_path, target)
        temp_file_path = None

        new_hash = compute_file_hash(backup_bytes)
        new_mtime = target.stat().st_mtime
    except PermissionError as e:
        raise AppError(ErrorCode.FILE_OPERATION_ERROR, f"還原檔案權限不足：{e}")
    except OSError as e:
        raise AppError(ErrorCode.FILE_OPERATION_ERROR, f"還原操作失敗：{e}")
    finally:
        if temp_file_path and temp_file_path.exists():
            try:
                temp_file_path.unlink()
            except OSError:
                pass

    # 原因：只更新同步基準（hash/mtime），不碰 body 與 updated_at，所以沒有 STALE_VERSION 窗口，Editor 也不必重建。
    # 還原後卡片與檔案刻意分歧；要讓卡片跟上時，使用者再按「讀入」。
    with session(request, write=True) as conn:
        save_file_state(conn, card_id, new_hash, new_mtime)
        return {
            "card": card_detail(conn, card_id),
            "mtime": new_mtime,
            "message": "已還原檔案的上一版備份（卡片內文未變動）",
        }


