            "board_questions": [dict(r) for r in conn.execute(BOARD_QUESTIONS_EXPORT_SQL).fetchall()],
            "question_relations": [dict(r) for r in conn.execute(QUESTION_RELATIONS_EXPORT_SQL).fetchall()],
