from .schemas import SyncSaveFileRequest, SystemFilePickRequest

_TK_PICKER_SCRIPT = """
import json, os, sys, tkinter as tk
from tkinter import filedialog

cfg = json.loads(sys.argv[1])
root = tk.Tk()
root.withdraw()
try:
    root.attributes("-topmost", True)
except Exception:
    pass

init_dir = cfg.get("init_dir") or os.path.expanduser("~")
init_file = cfg.get("init_file") or ""
title = cfg.get("title") or "選取檔案"

if cfg.get("mode") == "save":
    filetypes = [("JSON 備份檔", "*.json"), ("所有檔案", "*.*")]
    path = filedialog.asksaveasfilename(
        parent=root,
        title=title,
        initialdir=init_dir,
        initialfile=init_file or "cardboard_auto_backup.json",
        defaultextension=".json",
        filetypes=filetypes,
        confirmoverwrite=False,
    )
else:
    path = filedialog.askopenfilename(
        parent=root,
        title=title,
        initialdir=init_dir,
        initialfile=init_file,
    )

root.destroy()
print(json.dumps({"path": path or ""}), flush=True)
"""


@router.post("/system/pick-file")
def pick_system_file(payload: SystemFilePickRequest):
    """喚起本機作業系統原生檔案選取視窗，回傳經過安全驗證的絕對路徑。"""
    init_dir = ""
    init_file = payload.default_name or ""
    if payload.initial_path and payload.initial_path.strip():
        try:
            p = Path(os.path.expanduser(payload.initial_path.strip()))
            if p.is_dir():
                init_dir = str(p)
            elif p.parent.is_dir():
                init_dir = str(p.parent)
                if not init_file:
                    init_file = p.name
        except OSError:
            pass

    cfg_json = json.dumps({
        "mode": payload.mode,
        "title": payload.title,
        "init_dir": init_dir,
        "init_file": init_file,
    })
    try:
        proc = subprocess.run(
            [sys.executable, "-c", _TK_PICKER_SCRIPT, cfg_json],
            capture_output=True,
            text=True,
            encoding="utf-8",
            timeout=300,
        )
    except subprocess.TimeoutExpired:
        raise AppError(ErrorCode.FILE_OPERATION_ERROR, "檔案選取視窗逾時關閉")
    except OSError as e:
        raise AppError(ErrorCode.FILE_OPERATION_ERROR, f"無法啟動系統檔案選取視窗：{e}")

    if proc.returncode != 0:
        err_msg = (proc.stderr or "").strip()
        raise AppError(ErrorCode.FILE_OPERATION_ERROR, f"開啟檔案選取視窗失敗：{err_msg or '未知錯誤'}")

    try:
        out = json.loads(proc.stdout.strip().splitlines()[-1])
        raw_picked = (out.get("path") or "").strip()
    except (ValueError, IndexError) as e:
        raise AppError(ErrorCode.FILE_OPERATION_ERROR, f"解析選取檔案路徑失敗：{e}")

    if not raw_picked:
        return {"cancelled": True, "path": None}

    target = resolve_safe_path(raw_picked)
    return {"cancelled": False, "path": str(target)}


@router.post("/sync/save-file")
def sync_save_file(payload: SyncSaveFileRequest, request: Request):
    """將當前電腦端完整資料快照以原子替換方式安全覆寫至本機硬碟的指定檔案路徑。"""
    target = resolve_safe_path(payload.target_path)
    pkg_data = sync_export(request)
    out_bytes = json.dumps(pkg_data, ensure_ascii=False, indent=2).encode("utf-8")

    temp_file_path: Optional[Path] = None
    try:
        with tempfile.NamedTemporaryFile("wb", dir=str(target.parent), delete=False) as tf:
            temp_file_path = Path(tf.name)
            tf.write(out_bytes)
            tf.flush()
            os.fsync(tf.fileno())
        os.replace(temp_file_path, target)
        temp_file_path = None
    except PermissionError as e:
        raise AppError(ErrorCode.FILE_OPERATION_ERROR, f"寫入備份檔案權限不足：{e}")
    except OSError as e:
        raise AppError(ErrorCode.FILE_OPERATION_ERROR, f"寫入備份檔案失敗：{e}")
    finally:
        if temp_file_path and temp_file_path.exists():
            try:
                temp_file_path.unlink()
            except OSError:
                pass

    return {"saved": True, "path": str(target), "exported_at": pkg_data["exported_at"]}


@router.post("/sync/overwrite")
def sync_overwrite(pkg: SyncPackage, request: Request):
    """【選項 1-C】完整覆蓋還原：在單一 SQLite 交易內清空資料表，並 100% 依外鍵相依順序寫入備份檔內容。"""
    daily_pruned = {"bindings": 0, "converted_refs": 0}  # 封包不含日誌時，補不回的綁定／已轉卡片標記數量
    notes_pruned = 0  # 封包不含靈感筆記時，因所屬白板已不存在而補不回的便利貼數量
    questions_pruned = 0  # 封包不含問題白板結構時，因白板或母白板已不存在而補不回的問題白板數量
    relations_pruned = 0  # 封包不含問題關聯時，因任一端白板已不存在而補不回的關聯數量
    images_pruned = 0  # 封包不含白板圖片時，因所屬白板已不存在而補不回的圖片數量
    image_links_pruned = 0  # 封包不含白板圖片時，因圖片已捨棄或卡片不在同一塊白板上而補不回的連線數量
    # 原因：下面的清空與重灌依賴 foreign_keys = OFF（不連鎖刪除、可任意順序清表）；
    # 在 BEGIN 之後才執行 PRAGMA 是空操作，所以改由 session 在開交易前關閉
    with session(request, write=True, enforce_fk=False) as conn:
        try:
            # 本機檔案綁定不在備份封包裡（匯出時已清空）：先記下來，覆蓋後對仍存在的卡片補回
            file_bindings = [
                (r["file_path"], r["file_hash"], r["file_mtime"], r["id"])
                for r in conn.execute(
                    "SELECT id, file_path, file_hash, file_mtime FROM cards WHERE file_path IS NOT NULL"
                )
            ]



            # 1. 清空所有舊資料（按相反外鍵順序）
            # 日誌（比照上面的 file_bindings）：封包有帶就整批覆蓋；沒帶就保留現有主題串，
            # 先記下綁定與已轉卡片標記並明確清掉（不依賴 FK 是否連鎖），覆蓋 cards 後對仍存在的卡片補回
            kept_bindings: list[tuple[str, str, str]] = []
            kept_converted: list[tuple[str, str]] = []
            if pkg.daily_streams is None:
                kept_bindings = [
                    (r["stream_id"], r["card_id"], r["created_at"])
                    for r in conn.execute("SELECT stream_id, card_id, created_at FROM daily_stream_cards")
                ]
                kept_converted = [
                    (r["converted_card_id"], r["id"])
                    for r in conn.execute(
                        "SELECT id, converted_card_id FROM daily_streams WHERE converted_card_id IS NOT NULL"
                    )
                ]
                conn.execute("DELETE FROM daily_stream_cards")
                conn.execute("UPDATE daily_streams SET converted_card_id = NULL")
            else:
                conn.execute("DELETE FROM daily_stream_cards")
                conn.execute("DELETE FROM daily_streams")
            # 原因：card_relations.pattern_id 是 ON DELETE RESTRICT，必須先於 relation_patterns 清掉；
            # 若封包為 iPad 封包或舊備份（兩者皆為空），先保留本機既有的句型與關係句，重灌時只修剪已不存在的卡片／標籤參照，避免靜默清空。
            preserve_rel_patterns = not pkg.relation_patterns and not pkg.card_relations
            kept_rel_patterns = (
                [dict(r) for r in conn.execute("SELECT id, label, template, bridge_tag_id, note, family, created_at FROM relation_patterns")]
                if preserve_rel_patterns
                else []
            )
            kept_card_relations = (
                [dict(r) for r in conn.execute("SELECT card_id, pattern_id, role_a, role_b, result, free_sentence, updated_at FROM card_relations")]
                if preserve_rel_patterns
                else []
            )
            conn.execute("DELETE FROM card_relations")
            conn.execute("DELETE FROM relation_patterns")
            # 文獻：封包沒帶 literature（舊備份、iPad 封包）時先留下本機的，重灌時只保留卡片仍存在的引用；
            # 原因：覆蓋期間 foreign_keys = OFF，不會連鎖刪除，必須由子到父明確刪除
            kept_lit = (
                {k: [dict(r) for r in conn.execute(sql).fetchall()] for k, sql in LITERATURE_EXPORT_SQL.items()}
                if pkg.literature is None
                else None
            )
            # 原因：foreign_keys = OFF 時不會連鎖刪除；座標必須在刪除前先留下，下面視封包有沒有帶決定要不要沿用
            local_placements = [dict(r) for r in conn.execute(LITERATURE_EXPORT_SQL["board_placements"])]
            conn.execute("DELETE FROM board_literatures")
            conn.execute("DELETE FROM card_literature")
            conn.execute("DELETE FROM literature_collection_items")
            conn.execute("DELETE FROM literature_collections")
            conn.execute("DELETE FROM literature")
            # 原因：覆蓋期間 foreign_keys = OFF，ON DELETE CASCADE 不會觸發，不明確刪除會留下孤兒並讓 foreign_key_check 失敗。
            # 封包沒帶便利貼（舊版匯出）時先留下本機的，下面重灌時只保留所屬白板仍存在者
            kept_notes = (
                [
                    dict(r)
                    for r in conn.execute(
                        "SELECT id, board_id, text, x, y, w, h, color, created_at FROM board_notes"
                    )
                ]
                if pkg.board_notes is None
                else []
            )
            # 問題白板結構：封包沒帶（舊備份、iPad 封包）時先留下本機的，下面重灌時只保留自己與母白板都仍存在者；
            # 原因同上：foreign_keys = OFF 時不會連鎖刪除，必須在刪 boards 之前明確清掉
            kept_questions = (
                [dict(r) for r in conn.execute(BOARD_QUESTIONS_EXPORT_SQL)] if pkg.board_questions is None else []
            )
            # 問題關聯：封包沒帶（舊備份、iPad 封包）時先留下本機的，下面重灌時只保留兩端白板仍存在者；
            # 必須在刪 board_questions／boards 之前明確清掉，否則不是被連鎖刪除就是留下孤兒讓 foreign_key_check 整批失敗
            kept_relations = (
                [dict(r) for r in conn.execute(QUESTION_RELATIONS_EXPORT_SQL)] if pkg.question_relations is None else []
            )
            # 白板圖片與圖片連線：封包沒帶（舊備份、iPad 封包）時先留下本機的，下面重灌時只保留仍成立者。
            # 原因：必須在 DELETE FROM board_cards 之前留下——foreign_keys = OFF 擋不住 trg_board_cards_drop_image_links，
            # 刪 board_cards 會連線一起刪掉，晚留就會讓本機連線靜默消失；下面也明確先刪連線與圖片，不依賴 trigger 或連鎖
            kept_images = [dict(r) for r in conn.execute(BOARD_IMAGES_EXPORT_SQL)] if pkg.board_images is None else []
            kept_image_links = (
                [dict(r) for r in conn.execute(BOARD_IMAGE_LINKS_EXPORT_SQL)] if pkg.board_image_links is None else []
            )
            conn.execute("DELETE FROM board_image_links")
            conn.execute("DELETE FROM board_images")
            conn.execute("DELETE FROM question_relations")
            conn.execute("DELETE FROM board_questions")
            conn.execute("DELETE FROM board_notes")
            conn.execute("DELETE FROM board_groups")
            conn.execute("DELETE FROM board_cards")
            conn.execute("DELETE FROM boards")
            conn.execute("DELETE FROM links")
            conn.execute("DELETE FROM card_tags")
            conn.execute("DELETE FROM tag_aliases")
            conn.execute("DELETE FROM tags")
            conn.execute("DELETE FROM cards")

            # 2. 依序重灌：Cards
            for c in pkg.cards:
                conn.execute(
                    """INSERT INTO cards (id, title, body, card_type, curation_status, sources, created_at, updated_at)
                       VALUES (?, ?, ?, ?, ?, ?, ?, ?)""",
                    (
                        c.id,
                        c.title,
                        c.body,
                        c.card_type.value,
                        c.curation_status.value,
                        json.dumps(c.sources or [], ensure_ascii=False),
                        c.created_at,
                        c.updated_at,
                    ),
                )

            for fp, fh, fm, cid in file_bindings:
                conn.execute(
                    "UPDATE cards SET file_path = ?, file_hash = ?, file_mtime = ? WHERE id = ?",
                    (fp, fh, fm, cid),
                )

            # 3. 依序重灌：Tags（依 parent_id 拓撲順序保證父先於子）
            tag_map = {t.id: t for t in pkg.tags}
            pending_tags = list(pkg.tags)
            inserted_tags: set[str] = set()
            while pending_tags:
                ready = [t for t in pending_tags if t.parent_id is None or t.parent_id in inserted_tags]
                if not ready:
                    ready = pending_tags
                for t in ready:
                    conn.execute(
                        """INSERT OR REPLACE INTO tags (id, name, axis, facet, definition, parent_id, created_at)
                           VALUES (?, ?, ?, ?, ?, ?, ?)""",
                        (t.id, t.name, t.axis.normalized(), t.facet, t.definition, t.parent_id, utc_now()),
                    )
                    for a in t.aliases:
                        conn.execute(
                            "INSERT OR REPLACE INTO tag_aliases (alias, tag_id, created_at) VALUES (?, ?, ?)",
                            (a, t.id, utc_now()),
                        )
                    inserted_tags.add(t.id)
                ready_ids = {t.id for t in ready}
                pending_tags = [t for t in pending_tags if t.id not in ready_ids]

            # 4. 依序重灌：CardTags & Links
            for ct in pkg.card_tags:
                conn.execute("INSERT OR REPLACE INTO card_tags (card_id, tag_id) VALUES (?, ?)", (ct.card_id, ct.tag_id))
            for l in pkg.links:
                conn.execute(
                    """INSERT OR REPLACE INTO links (source_id, target_id, relation_type, status, reason, created_at)
                       VALUES (?, ?, ?, ?, ?, ?)""",
                    (l.source_id, l.target_id, l.relation_type.value, l.status.value, l.reason, utc_now()),
                )

            # 5. 依序重灌：Boards, BoardCards, BoardGroups
            now = utc_now()
            for b in pkg.boards:
                conn.execute(
                    "INSERT INTO boards (id, name, created_at, updated_at) VALUES (?, ?, ?, ?)",
                    (b.id, b.name, now, now),
                )
            for bc in pkg.board_cards:
                conn.execute(
                    "INSERT INTO board_cards (board_id, card_id, x, y, w, h, z) VALUES (?, ?, ?, ?, ?, ?, 0)",
                    (
                        bc.board_id,
                        bc.card_id,
                        bc.x if bc.x is not None else BOARD_ORIGIN,  # 座標 0 是合法值，不能用 or 當成缺值
                        bc.y if bc.y is not None else BOARD_ORIGIN,
                        bc.w or DEFAULT_CARD_WIDTH,
                        bc.h,
                    ),
                )
            for bg in pkg.board_groups:
                conn.execute(
                    """INSERT INTO board_groups (id, board_id, label, x, y, w, h, color, created_at)
                       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)""",
                    (bg.id, bg.board_id, bg.label, bg.x, bg.y, bg.w, bg.h, bg.color, now),
                )

            # 便利貼：封包有帶就以封包為準（所屬白板不存在會被 foreign_key_check 擋下，與分組框一致）；
            # 沒帶就沿用上面留下的本機資料，且只保留所屬白板仍存在者
            board_ids = {b.id for b in pkg.boards}
            if pkg.board_notes is not None:
                note_rows = [
                    (
                        n.id, n.board_id, n.text, n.x, n.y, n.w,
                        n.h if n.h is not None else NOTE_DEFAULT_H,  # 舊封包沒有高度：補預設高度
                        n.color, n.created_at or now,
                    )
                    for n in pkg.board_notes
                ]
            else:
                note_rows = [
                    (n["id"], n["board_id"], n["text"], n["x"], n["y"], n["w"], n["h"], n["color"], n["created_at"])
                    for n in kept_notes
                    if n["board_id"] in board_ids
                ]
                notes_pruned = len(kept_notes) - len(note_rows)
            for row in note_rows:
                conn.execute(
                    """INSERT INTO board_notes (id, board_id, text, x, y, w, h, color, created_at)
                       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)""",
                    row,
                )

            # 白板圖片與圖片連線：封包有帶就以封包為準（所屬白板不存在會被 foreign_key_check 擋下）；沒帶就沿用本機的，
            # 只保留所屬白板仍存在的圖片，以及圖片仍在、卡片仍在同一塊白板上的連線；補不回的筆數回報在 images_pruned／image_links_pruned。
            # 連線的不變式（卡片必須在圖片所在的白板上）平常由 trigger 與端點維持，覆蓋期間逐表重灌，必須在這裡自己檢查
            restored_on_board = {(bc.board_id, bc.card_id) for bc in pkg.board_cards}
            if pkg.board_images is not None:
                image_rows = [i.model_dump(mode="json") for i in pkg.board_images]
            else:
                image_rows = [i for i in kept_images if i["board_id"] in board_ids]
                images_pruned = len(kept_images) - len(image_rows)
            image_board = {i["id"]: i["board_id"] for i in image_rows}
            if pkg.board_image_links is not None:
                image_link_rows = [l.model_dump(mode="json") for l in pkg.board_image_links]
                bad_links = [
                    l for l in image_link_rows if (image_board.get(l["image_id"]), l["card_id"]) not in restored_on_board
                ]
                if bad_links:
                    raise AppError(
                        ErrorCode.VALIDATION_ERROR,
                        "備份中有圖片連線的圖片或卡片不在同一塊白板上，無法還原",
                        {"links": bad_links[:20], "count": len(bad_links)},
                    )
            else:
                image_link_rows = [
                    l for l in kept_image_links if (image_board.get(l["image_id"]), l["card_id"]) in restored_on_board
                ]
                image_links_pruned = len(kept_image_links) - len(image_link_rows)
            for i in image_rows:
                conn.execute(
                    """INSERT INTO board_images (id, board_id, media_id, x, y, w, h, crop_x, crop_y, crop_w, crop_h, created_at)
                       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
                    (
                        i["id"], i["board_id"], i["media_id"], i["x"], i["y"], i["w"], i["h"],
                        i["crop_x"], i["crop_y"], i["crop_w"], i["crop_h"], i["created_at"],
                    ),
                )
            for l in image_link_rows:
                conn.execute(
                    "INSERT INTO board_image_links (image_id, card_id, created_at) VALUES (?, ?, ?)",
                    (l["image_id"], l["card_id"], l["created_at"]),
                )

            # 問題白板結構：封包有帶就以封包為準（所屬白板不存在會被 foreign_key_check 擋下）；沒帶就沿用本機的，
            # 只保留「自己仍存在、且（若是未封存的）母白板也仍存在」者，被捨棄的筆數回報在 questions_pruned，不默默吞掉
            if pkg.board_questions is not None:
                question_rows = [q.model_dump(mode="json") for q in pkg.board_questions]
            else:
                question_rows = [
                    q
                    for q in kept_questions
                    if q["board_id"] in board_ids and (q["parent_board_id"] is None or q["parent_board_id"] in board_ids)
                ]
                questions_pruned = len(kept_questions) - len(question_rows)
            for q in question_rows:
                conn.execute(
                    """INSERT INTO board_questions (board_id, parent_board_id, kind, status, reason, x, y, w, h,
                                                    archived_at, archive_reason, archive_path, created_at)
                       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
                    (
                        q["board_id"], q["parent_board_id"], q["kind"], q["status"], q["reason"],
                        q["x"], q["y"], q["w"], q["h"],
                        q["archived_at"], q["archive_reason"], q["archive_path"], q["created_at"],
                    ),
                )

            # 問題關聯：封包有帶就以封包為準（任一端白板不存在會被 foreign_key_check 擋下）；沒帶就沿用本機的，
            # 只保留兩端白板都仍存在者（一般白板也可參與關聯，所以以 board_ids 判斷，不是問題白板），
            # 補不回的筆數回報在 relations_pruned，不默默吞掉
            if pkg.question_relations is not None:
                relation_rows = [r.model_dump(mode="json") for r in pkg.question_relations]
            else:
                relation_rows = [r for r in kept_relations if r["board_a"] in board_ids and r["board_b"] in board_ids]
                relations_pruned = len(kept_relations) - len(relation_rows)
            for r in relation_rows:
                conn.execute(
                    "INSERT INTO question_relations (id, board_a, board_b, relation_type, created_at) VALUES (?, ?, ?, ?, ?)",
                    (r["id"], r["board_a"], r["board_b"], r["relation_type"], r["created_at"]),
                )

            # 文獻：封包有帶就以封包為準；沒帶就用上面留下的本機資料（引用只保留卡片仍存在者）
            if pkg.literature is not None:
                lit = pkg.literature.model_dump()
            else:
                keep_card_ids = {c.id for c in pkg.cards}
                lit = {
                    **kept_lit,
                    "citations": [c for c in kept_lit["citations"] if c["card_id"] in keep_card_ids],
                    "board_placements": None,  # 交給下面統一沿用本機座標並過濾
                }
            for r in lit["items"]:
                conn.execute(
                    """INSERT INTO literature (id, title, body, author, url, captured_on, created_at, updated_at)
                       VALUES (?, ?, ?, ?, ?, ?, ?, ?)""",
                    (r["id"], r["title"], r["body"], r["author"], r["url"], r["captured_on"], r["created_at"], r["updated_at"]),
                )
            for r in lit["collections"]:
                conn.execute(
                    "INSERT INTO literature_collections (id, name, created_at) VALUES (?, ?, ?)",
                    (r["id"], r["name"], r["created_at"]),
                )
            for r in lit["collection_items"]:
                conn.execute(
                    "INSERT INTO literature_collection_items (collection_id, literature_id) VALUES (?, ?)",
                    (r["collection_id"], r["literature_id"]),
                )
            for r in lit["citations"]:
                conn.execute(
                    """INSERT INTO card_literature (id, card_id, literature_id, locator, created_at)
                       VALUES (?, ?, ?, ?, ?)""",
                    (r["id"], r["card_id"], r["literature_id"], r["locator"], r["created_at"]),
                )

            # 白板文獻節點：封包的文獻區塊有帶座標就以它為準（所屬白板或文獻不存在會被 foreign_key_check 擋下）；
            # 沒帶（舊備份、或整個沒有文獻區塊）就沿用上面留下的本機座標，只保留所屬白板與文獻都仍存在者
            placements = lit.get("board_placements")
            if placements is None:
                lit_ids = {r["id"] for r in lit["items"]}
                placements = [
                    p for p in local_placements if p["board_id"] in board_ids and p["literature_id"] in lit_ids
                ]
            for r in placements:
                conn.execute(
                    """INSERT INTO board_literatures (board_id, literature_id, x, y, w, h, z)
                       VALUES (?, ?, ?, ?, ?, ?, ?)""",
                    (r["board_id"], r["literature_id"], r["x"], r["y"], r["w"], r["h"], r["z"]),
                )

            # 日誌：封包有帶就以封包為準（轉出的卡片或綁定的卡片不在封包裡，會被 foreign_key_check 擋下）；
            # 沒帶就沿用上面留下的主題串，綁定與已轉卡片標記只補回「卡片仍存在」者，補不回的筆數回報在 daily_pruned。
            # 原因：上面已先清掉日誌（沒帶時只清綁定與標記），這裡不寫回的話，完整備份還原後所有主題串都會消失
            if pkg.daily_streams is not None:
                for s in pkg.daily_streams:
                    conn.execute(
                        """INSERT INTO daily_streams (id, day, position, title, status, recall_text, review_text, peeked_at,
                                                      unlocked_at, converted_card_id, created_at, updated_at)
                           VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
                        (
                            s.id, s.day, s.position, s.title, s.status.value, s.recall_text, s.review_text, s.peeked_at,
                            s.unlocked_at, s.converted_card_id, s.created_at, s.updated_at,
                        ),
                    )
                for b in pkg.daily_stream_cards or []:
                    conn.execute(
                        "INSERT INTO daily_stream_cards (stream_id, card_id, created_at) VALUES (?, ?, ?)",
                        (b.stream_id, b.card_id, b.created_at),
                    )
            else:
                kept_card_ids = {c.id for c in pkg.cards}
                for stream_id, card_id, created_at in kept_bindings:
                    if card_id in kept_card_ids:
                        conn.execute(
                            "INSERT INTO daily_stream_cards (stream_id, card_id, created_at) VALUES (?, ?, ?)",
                            (stream_id, card_id, created_at),
                        )
                    else:
                        daily_pruned["bindings"] += 1
                for card_id, stream_id in kept_converted:
                    if card_id in kept_card_ids:
                        conn.execute("UPDATE daily_streams SET converted_card_id = ? WHERE id = ?", (card_id, stream_id))
                    else:
                        daily_pruned["converted_refs"] += 1

            # 6. 依序重灌：RelationPatterns & CardRelations（若備份檔有提供）
            if preserve_rel_patterns:
                keep_card_ids = {c.id for c in pkg.cards}
                valid_patterns = [rp for rp in kept_rel_patterns if rp["bridge_tag_id"] in inserted_tags]
                valid_pattern_ids = {rp["id"] for rp in valid_patterns}
                for rp in valid_patterns:
                    conn.execute(
                        """INSERT OR REPLACE INTO relation_patterns (id, label, template, bridge_tag_id, note, family, created_at)
                           VALUES (?, ?, ?, ?, ?, ?, ?)""",
                        (rp["id"], rp["label"], rp["template"], rp["bridge_tag_id"], rp["note"], rp["family"], rp["created_at"]),
                    )
                for cr in kept_card_relations:
                    if cr["card_id"] in keep_card_ids and (cr["pattern_id"] is None or cr["pattern_id"] in valid_pattern_ids):
                        conn.execute(
                            """INSERT OR REPLACE INTO card_relations (card_id, pattern_id, role_a, role_b, result, free_sentence, updated_at)
                               VALUES (?, ?, ?, ?, ?, ?, ?)""",
                            (cr["card_id"], cr["pattern_id"], cr["role_a"], cr["role_b"], cr["result"], cr["free_sentence"], cr["updated_at"]),
                        )
            else:
                for rp in pkg.relation_patterns:
                    conn.execute(
                        """INSERT OR REPLACE INTO relation_patterns (id, label, template, bridge_tag_id, note, family, created_at)
                           VALUES (?, ?, ?, ?, ?, ?, ?)""",
                        (rp.id, rp.label, rp.template, rp.bridge_tag_id, rp.note, rp.family, now),
                    )
                for cr in pkg.card_relations:
                    conn.execute(
                        """INSERT OR REPLACE INTO card_relations (card_id, pattern_id, role_a, role_b, result, free_sentence, updated_at)
                           VALUES (?, ?, ?, ?, ?, ?, ?)""",
                        (cr.card_id, cr.pattern_id, cr.role_a, cr.role_b, cr.result, cr.free_sentence, cr.updated_at),
                    )

            fk_errors = conn.execute("PRAGMA foreign_key_check").fetchall()
            if fk_errors:
                raise AppError(ErrorCode.VALIDATION_ERROR, f"還原外鍵驗證失敗：{fk_errors}")
        finally:
            conn.execute("PRAGMA foreign_keys = ON")

    return {
        "restored": True,
        "cards_count": len(pkg.cards),
        "boards_count": len(pkg.boards),
        "tags_count": len(pkg.tags),
        "daily_pruned": daily_pruned,
        "notes_pruned": notes_pruned,
        "questions_pruned": questions_pruned,
        "relations_pruned": relations_pruned,
        "images_pruned": images_pruned,
        "image_links_pruned": image_links_pruned,
    }


@router.post("/sync/apply")
def sync_apply(payload: SyncApplyRequest, request: Request):
    pkg = payload.package
    card_map = {c.id: c for c in pkg.cards}
    tag_map = {t.id: t for t in pkg.tags}
    board_map = {b.id: b for b in pkg.boards}

    applied = {
        "cards_added": 0,
        "cards_updated": 0,
        "tags_added": 0,
        "tags_updated": 0,
        "card_tags_added": 0,
        "links_added": 0,
        "board_cards_added": 0,
        "tags_merged": 0,
        "board_cards_skipped": 0,
        "boards_created": 0,
    }

    with session(request, write=True) as conn:
        # @depends-on schema.sql::tags.parent_id（即時外鍵，父標籤必須先於子標籤存在）
        # @depends-on schema.sql::uq_tags_sibling / uq_tags_root（同層同名唯一）
        # assumption: 封包內 tags 的順序不保證父先於子（iPad 端依 Dexie 主鍵順序匯出）
        # assumption: 同層（同父；最上層則同 axis+facet）同名＝同一個標籤，電腦端索引與 iPad createTag 皆以此為契約
        # if broken: 父標籤找不到→明確 422；同名→併入電腦端既有標籤（不覆蓋其定義）並計入 tags_merged；
        #            其他約束違反（CHECK 等）→明確 422，不再被 OR IGNORE 吞掉
        tag_remap: dict[str, str] = {}  # iPad 標籤 id → 電腦端既有標籤 id，card_tags 要照此改指
        known_tag_ids = {r["id"] for r in conn.execute("SELECT id FROM tags").fetchall()}
        pending_tags = [tag_map[tid] for tid in payload.tag_ids_to_add if tid in tag_map]
        while pending_tags:
            ready = [t for t in pending_tags if t.parent_id is None or t.parent_id in known_tag_ids]
            if not ready:
                raise AppError(
                    ErrorCode.VALIDATION_ERROR,
                    "封包中有標籤的父標籤在電腦端與封包中都找不到，無法套用",
                    {"tags": [{"id": t.id, "name": t.name, "parent_id": t.parent_id} for t in pending_tags]},
                )
            for t in ready:
                axis_val = t.axis.normalized()
                parent_id = tag_remap.get(t.parent_id, t.parent_id) if t.parent_id else None
                if parent_id is not None:
                    dup = conn.execute(
                        "SELECT id FROM tags WHERE parent_id = ? AND name = ?", (parent_id, t.name)
                    ).fetchone()
                else:
                    dup = conn.execute(
                        """SELECT id FROM tags
                           WHERE parent_id IS NULL AND axis = ? AND COALESCE(facet, '') = ? AND name = ?""",
                        (axis_val, t.facet or "", t.name),
                    ).fetchone()
                if dup is not None:
                    if dup["id"] != t.id:  # id 相同代表這包已套用過，重送時不重複計數
                        tag_remap[t.id] = dup["id"]
                        applied["tags_merged"] += 1
                else:
                    cur = conn.execute(
                        """INSERT OR IGNORE INTO tags (id, name, axis, facet, definition, parent_id, created_at)
                           VALUES (?, ?, ?, ?, ?, ?, ?)""",
                        (t.id, t.name, axis_val, t.facet, t.definition, parent_id, utc_now()),
                    )
                    if cur.rowcount == 0:
                        raise AppError(
                            ErrorCode.VALIDATION_ERROR,
                            "標籤無法寫入（違反資料表約束）",
                            {"tag": {"id": t.id, "name": t.name, "axis": axis_val, "parent_id": parent_id}},
                        )
                    applied["tags_added"] += 1
                for a in t.aliases:
                    conn.execute(
                        "INSERT OR IGNORE INTO tag_aliases (alias, tag_id, created_at) VALUES (?, ?, ?)",
                        (a, tag_remap.get(t.id, t.id), utc_now()),
                    )
                known_tag_ids.add(t.id)
            ready_ids = {t.id for t in ready}
            pending_tags = [t for t in pending_tags if t.id not in ready_ids]

                # @depends-on SyncModal.tsx::applyChanges（前端固定送 tag_ids_to_update=[]）
        # assumption: 標籤沒有 updated_at，無法判斷 iPad 與電腦端誰較新，套用會讓舊值回退新改動
        # if broken: 有呼叫端送了非空清單→明確 422，不默默改標籤，也不讓環／UNIQUE 變成 500
        if payload.tag_ids_to_update:
            raise AppError(
                ErrorCode.VALIDATION_ERROR,
                "目前不支援套用標籤更新（標籤沒有修改時間，無法判斷哪邊較新）",
                {"tag_ids": payload.tag_ids_to_update},
            )

        for cid in payload.card_ids_to_add:
            c = card_map.get(cid)
            if not c:
                continue
            cur = conn.execute(
                """INSERT OR IGNORE INTO cards (id, title, body, card_type, curation_status, sources, created_at, updated_at)
                   VALUES (?, ?, ?, ?, ?, ?, ?, ?)""",
                (
                    c.id,
                    c.title,
                    c.body,
                    c.card_type.value,
                    c.curation_status.value,
                    json.dumps(c.sources or [], ensure_ascii=False),
                    c.created_at,
                    c.updated_at,
                ),
            )
            applied["cards_added"] += cur.rowcount

        for cid in payload.card_ids_to_update:
            c = card_map.get(cid)
            if not c:
                continue
            # 若電腦端卡片在匯出/比對期間剛被修改（updated_at 晚於封包匯出時間），拒絕靜默覆蓋並明確報錯 409
            cur_row = conn.execute("SELECT title, updated_at FROM cards WHERE id = ?", (c.id,)).fetchone()
            if cur_row and cur_row["updated_at"] > pkg.exported_at and cur_row["updated_at"] > c.updated_at:
                raise AppError(
                    ErrorCode.STALE_VERSION,
                    f"卡片「{cur_row['title'] or c.id}」在同步期間剛在電腦端被修改過，請重新拉取比對差異後再套用",
                    {"card_id": c.id, "pc_updated_at": cur_row["updated_at"]},
                )
            conn.execute(
                """UPDATE cards SET title = ?, body = ?, card_type = ?, curation_status = ?,
                   sources = COALESCE(?, sources), updated_at = ?
                   WHERE id = ?""",
                (
                    c.title,
                    c.body,
                    c.card_type.value,
                    c.curation_status.value,
                    json.dumps(c.sources, ensure_ascii=False) if c.sources is not None else None,
                    c.updated_at,
                    c.id,
                ),
            )
            applied["cards_updated"] += 1

        for ct in payload.card_tags_to_add:
            tag_id = tag_remap.get(ct.tag_id, ct.tag_id)
            if conn.execute("SELECT 1 FROM cards WHERE id = ?", (ct.card_id,)).fetchone() and conn.execute(
                "SELECT 1 FROM tags WHERE id = ?", (tag_id,)
            ).fetchone():
                conn.execute(
                    "INSERT OR IGNORE INTO card_tags (card_id, tag_id) VALUES (?, ?)",
                    (ct.card_id, tag_id),
                )
                applied["card_tags_added"] += 1

        for l in payload.links_to_add:
            if conn.execute("SELECT 1 FROM cards WHERE id = ?", (l.source_id,)).fetchone() and conn.execute(
                "SELECT 1 FROM cards WHERE id = ?", (l.target_id,)
            ).fetchone():
                conn.execute(
                    """INSERT OR REPLACE INTO links (source_id, target_id, relation_type, status, reason, created_at)
                       VALUES (?, ?, ?, ?, ?, ?)""",
                    (l.source_id, l.target_id, l.relation_type.value, l.status.value, l.reason, utc_now()),
                )
                applied["links_added"] += 1

        # 原因：iPad 新開的白板電腦端沒有，歸屬被丟掉；且舊寫法逐張疊放，不會避開既有卡片。
        # 做法：缺的白板用封包內的 id／名稱建立；同一塊白板的新卡片擺成方陣，放在現有卡片範圍正下方。
        # @depends-on schema.sql::boards（id, name, created_at, updated_at 皆 NOT NULL）
        placements: dict[str, list[Any]] = {}
        for bc in payload.board_cards_to_add:
            if conn.execute("SELECT 1 FROM cards WHERE id = ?", (bc.card_id,)).fetchone() is None:
                continue  # 卡片未被勾選套用，歸屬跟著略過：這是使用者的選擇，不是異常
            if conn.execute(
                "SELECT 1 FROM board_cards WHERE board_id = ? AND card_id = ?", (bc.board_id, bc.card_id)
            ).fetchone():
                continue  # 已在白板上（重送封包），不重排、不重複計數
            placements.setdefault(bc.board_id, []).append(bc)

        for board_id, items in placements.items():
            if conn.execute("SELECT 1 FROM boards WHERE id = ?", (board_id,)).fetchone() is None:
                src = board_map.get(board_id)
                if src is None:  # 封包自己都沒有這塊白板，無從建立：回報而非默默略過
                    applied["board_cards_skipped"] += len(items)
                    continue
                # 原因：boards 的 created_at、updated_at 都是 NOT NULL（schema.sql:124），少一個會直接 500
                now = utc_now()
                conn.execute(
                    "INSERT INTO boards (id, name, created_at, updated_at) VALUES (?, ?, ?, ?)",
                    (board_id, src.name, now, now),
                )
                applied["boards_created"] += 1

            box = conn.execute(
                "SELECT MIN(x) AS min_x, MAX(y + COALESCE(h, ?)) AS max_bottom FROM board_cards WHERE board_id = ?",
                (FALLBACK_CARD_HEIGHT, board_id),
            ).fetchone()
            if box["min_x"] is None:
                x0, y0 = BOARD_ORIGIN, BOARD_ORIGIN
            else:
                x0, y0 = box["min_x"], box["max_bottom"] + GRID_GAP

            cols = math.ceil(math.sqrt(len(items)))
            cell_w = max((bc.w or DEFAULT_CARD_WIDTH) for bc in items) + GRID_GAP
            cell_h = max((bc.h or FALLBACK_CARD_HEIGHT) for bc in items) + GRID_GAP
            for i, bc in enumerate(items):
                conn.execute(
                    """INSERT OR IGNORE INTO board_cards (board_id, card_id, x, y, w, h, z)
                       VALUES (?, ?, ?, ?, ?, ?, 0)""",
                    (
                        board_id,
                        bc.card_id,
                        x0 + (i % cols) * cell_w,
                        y0 + (i // cols) * cell_h,
                        bc.w or DEFAULT_CARD_WIDTH,
                        bc.h,
                    ),
                )
                applied["board_cards_added"] += 1

    return {"applied": applied}
