def _board(conn, board_id):
    row = conn.execute("SELECT * FROM boards WHERE id = ?", (board_id,)).fetchone()
    if row is None:
        raise AppError(ErrorCode.NOT_FOUND, "白板不存在", {"board_id": board_id})
    return row


def _writable_board(conn, board_id):
    """寫入用：和 _board 一樣，但已封存的問題白板是唯讀紀錄，不能再加卡片、移動、改名或刪除裡面的東西。
    （永久刪除整塊白板走 delete_board，不經過這裡；改名不算「動內容」，維持可用。）"""
    row = _board(conn, board_id)
    q = conn.execute("SELECT archived_at FROM board_questions WHERE board_id = ?", (board_id,)).fetchone()
    if q is not None and q["archived_at"] is not None:
        raise AppError(ErrorCode.INVALID_STATE, "這塊問題已封存，只能查看；要再使用請先永久刪除", {"board_id": board_id})
    return row


# 問題白板（一塊問題白板＝一塊普通白板加 board_questions 一列；一般白板沒有這一列）
# @depends-on db.py::BOARD_QUESTIONS_DDL / types.ts::BoardQuestion / cards.py::BOARD_QUESTIONS_EXPORT_SQL（欄位變動時一起改）
_QUESTION_KEYS = (
    "parent_board_id",
    "kind",
    "status",
    "reason",
    "x",
    "y",
    "w",
    "h",
    "archived_at",
    "archive_reason",
    "archive_path",
    "created_at",
)
_QUESTION_COLUMNS = ", ".join(f"bq.{k}" for k in _QUESTION_KEYS)
# 這些表以 board_id 指向白板，是「白板自己擁有、隨白板消失」的內容；卡片與文獻本體不在其中
_BOARD_CONTENT_TABLES = {
    "cards": "board_cards",
    "literatures": "board_literatures",
    "notes": "board_notes",
    "groups": "board_groups",
    "images": "board_images",
}
# 子問題提升一級時，在新母畫布上從被刪節點位置起橫向排開的間距
QUESTION_PROMOTE_GAP = 32.0
# 新問題（或移入的問題）放在母畫布最右邊子問題的右側；沒有子問題時放左上角
# @depends-on QuestionNavigator.tsx::NEW_NODE_GAP／addQuestion、ConceptGraph.tsx::NewBoardDialog（同一條規則的前端副本，改規則時一起改）
QUESTION_NEW_GAP = 40.0
QUESTION_FIRST_POS = 80.0
# 問題節點的列（畫布節點與導航器共用）：item_count＝卡片＋文獻＋靈感筆記；child_count 不含已封存者
_QUESTION_NODE_SELECT = """SELECT bq.board_id, b.name, bq.kind, bq.status, bq.reason, bq.x, bq.y, bq.w, bq.h,
                      (SELECT COUNT(*) FROM board_questions c
                        WHERE c.parent_board_id = bq.board_id AND c.archived_at IS NULL) AS child_count,
                      (SELECT COUNT(*) FROM board_cards WHERE board_id = bq.board_id) AS card_count,
                      (SELECT COUNT(*) FROM board_literatures WHERE board_id = bq.board_id) AS literature_count,
                      (SELECT COUNT(*) FROM board_notes WHERE board_id = bq.board_id) AS note_count,
                      (SELECT COUNT(*) FROM board_cards WHERE board_id = bq.board_id)
                      + (SELECT COUNT(*) FROM board_literatures WHERE board_id = bq.board_id)
                      + (SELECT COUNT(*) FROM board_notes WHERE board_id = bq.board_id) AS item_count
               FROM board_questions bq JOIN boards b ON b.id = bq.board_id"""
移除重複的 _QUESTION_NODE_SELECT 常數定義，消除日後修改上方定義卻被下方靜默覆蓋的風險，且不影響任何外部或內部呼叫。


def _question_row(conn, board_id):
    """這塊白板的問題列；一般白板回傳 None。"""
    return conn.execute(
        f"SELECT {_QUESTION_COLUMNS} FROM board_questions bq WHERE bq.board_id = ?", (board_id,)
    ).fetchone()


def _question_info(row):
    """問題白板的欄位；一般白板（沒有問題列，或 LEFT JOIN 沒對到而 kind 為 None）回傳 None。"""
    if row is None or row["kind"] is None:
        return None
    return {k: row[k] for k in _QUESTION_KEYS}


def _board_contents(conn, board_id):
    return {
        key: conn.execute(f"SELECT COUNT(*) FROM {table} WHERE board_id = ?", (board_id,)).fetchone()[0]
        for key, table in _BOARD_CONTENT_TABLES.items()
    }


def _path_names(conn, board_id):
    """由最上層到這塊白板的名稱路徑（封存時留下的快照）。遇到循環就大聲報錯，不無窮迴圈。"""
    names, seen, cur = [], set(), board_id
    while cur is not None:
        if cur in seen:
            raise AppError(ErrorCode.CYCLE_DETECTED, "問題白板的上下層關係出現循環，資料異常", {"board_id": board_id})
        seen.add(cur)
        row = conn.execute(
            "SELECT b.name, bq.parent_board_id FROM boards b "
            "LEFT JOIN board_questions bq ON bq.board_id = b.id WHERE b.id = ?",
            (cur,),
        ).fetchone()
        if row is None:
            raise AppError(ErrorCode.NOT_FOUND, "白板不存在", {"board_id": cur})
        names.append(row["name"])
        cur = row["parent_board_id"]
    return " / ".join(reversed(names))


def _ancestors(conn, board_id):
    """由最上層到「這塊白板的母白板」的 [{id, name}]（不含自己）。遇到循環就大聲報錯。"""
    out, seen, cur = [], {board_id}, board_id
    while True:
        row = conn.execute("SELECT parent_board_id FROM board_questions WHERE board_id = ?", (cur,)).fetchone()
        cur = row["parent_board_id"] if row is not None else None
        if cur is None:
            break
        if cur in seen:
            raise AppError(ErrorCode.CYCLE_DETECTED, "問題白板的上下層關係出現循環，資料異常", {"board_id": board_id})
        seen.add(cur)
        b = conn.execute("SELECT id, name FROM boards WHERE id = ?", (cur,)).fetchone()
        if b is None:
            raise AppError(ErrorCode.NOT_FOUND, "白板不存在", {"board_id": cur})
        out.append({"id": b["id"], "name": b["name"]})
    out.reverse()
    return out
移除重複的 _ancestors 函式定義，保留唯一實作以維持與 _elsewhere、_related_boards 的既有內部契約。


def _descendants(conn, board_id):
    """自己以外的所有後代問題白板（含已封存者），由淺到深。UNION 去重，資料異常也不會無窮迴圈。"""
    rows = conn.execute(
        """WITH RECURSIVE sub(id) AS (
               SELECT ?
               UNION
               SELECT bq.board_id FROM board_questions bq JOIN sub s ON bq.parent_board_id = s.id
           )
           SELECT bq.board_id AS id, bq.parent_board_id, b.name, bq.archived_at
           FROM sub JOIN board_questions bq ON bq.board_id = sub.id JOIN boards b ON b.id = bq.board_id
           WHERE bq.board_id <> ?""",
        (board_id, board_id),
    ).fetchall()
    parent_of = {r["id"]: r["parent_board_id"] for r in rows}
    out = []
    for r in rows:
        depth, cur = 1, r["parent_board_id"]
        while cur is not None and cur != board_id:
            depth += 1
            cur = parent_of.get(cur)
        out.append(
            {
                "id": r["id"],
                "name": r["name"],
                "parent_board_id": r["parent_board_id"],
                "depth": depth,
                "archived": r["archived_at"] is not None,
            }
        )
    return sorted(out, key=lambda d: (d["depth"], d["name"]))


# 位置軸：舊資料可能還是 domain，與 list_cards 的 unclassified 判定同一集合
_LOCATION_AXES = {Axis.LOCATION.value, Axis.DOMAIN.value}


# 這張卡片還出現在哪些白板（徽章與點開的清單共用這一個判定，不要在別處重寫）。
# 同支＝目前白板的祖先或後代問題白板；其餘有放這張卡片的白板是他支。
# 已封存者不算他支：封存根節點已脫離母節點，無從判斷與目前白板的關係，也已不在使用中；
# 同支一律照算（目前白板本身已封存時，它的上下層也都已封存）。
# @depends-on 本檔 _ancestors／_descendants / types.ts::BoardElsewhere / CardNode.tsx（徽章）/ get_board 與 add_card_to_board 回傳的 "elsewhere"
def _elsewhere(conn, board_id, card_id=None):
    """card_id → {"same": [{id, name}], "other": [{id, name}]}；只含有出現在其他白板的卡片。給 card_id 時只查那一張。"""
    lineage = {a["id"] for a in _ancestors(conn, board_id)} | {d["id"] for d in _descendants(conn, board_id)}
    sql = """SELECT bc.card_id, b.id AS other_id, b.name, bq.archived_at
             FROM board_cards cur
             JOIN board_cards bc ON bc.card_id = cur.card_id AND bc.board_id <> cur.board_id
             JOIN boards b ON b.id = bc.board_id
             LEFT JOIN board_questions bq ON bq.board_id = b.id
             WHERE cur.board_id = ?"""
    params = [board_id]
    if card_id is not None:
        sql += " AND cur.card_id = ?"
        params.append(card_id)
    out = {}
    for r in conn.execute(sql + " ORDER BY b.name, b.id", params):
        if r["other_id"] in lineage:
            key = "same"
        elif r["archived_at"] is not None:
            continue
        else:
            key = "other"
        out.setdefault(r["card_id"], {"same": [], "other": []})[key].append({"id": r["other_id"], "name": r["name"]})
    return out


def _card_elsewhere(by_card, card_id):
    return by_card.get(card_id) or {"same": [], "other": []}


# 推薦用的「相關白板」：與這塊白板同支（祖先或後代）或有人工關聯的未封存白板 → {id: {id, name, kind}}。
# kind＝"tree"（同支）或 "relation"（人工關聯）；兩者皆是時記為 tree。已封存的不算（脫離路徑樹、已不在使用中）。
# @depends-on 本檔 _ancestors／_descendants／question_relations（任一端是這塊白板，不分方向與類型）/ types.ts::CardRecommendation.related_boards
def _related_boards(conn, board_id):
    found = {}
    for a in _ancestors(conn, board_id):
        found[a["id"]] = {"id": a["id"], "name": a["name"], "kind": "tree"}
    for d in _descendants(conn, board_id):
        found[d["id"]] = {"id": d["id"], "name": d["name"], "kind": "tree"}
    for r in conn.execute(
        """SELECT b.id, b.name FROM question_relations r
           JOIN boards b ON b.id = CASE WHEN r.board_a = ? THEN r.board_b ELSE r.board_a END
           WHERE r.board_a = ? OR r.board_b = ?""",
        (board_id, board_id, board_id),
    ):
        found.setdefault(r["id"], {"id": r["id"], "name": r["name"], "kind": "relation"})
    if not found:
        return {}
    marks = ",".join("?" * len(found))
    archived = {
        r["board_id"]
        for r in conn.execute(
            f"SELECT board_id FROM board_questions WHERE archived_at IS NOT NULL AND board_id IN ({marks})", list(found)
        )
    }
    return {k: v for k, v in found.items() if k not in archived}


# 以整塊白板為錨點的推薦（唯讀）。
# 卡片：與板上卡片共享標籤者。位置標籤（櫃位／抽屜／格子）連祖先一起比對，但每條分支只列最深的吻合層；
#       排序＝是否在相關白板上（同支或人工關聯，見 _related_boards，排最前）→ 吻合項數 → 位置深度 → 板上支持數 → 更新時間。
#       相關白板上的卡片即使沒有共享標籤也是候選；其餘沒有任何標籤的卡片不會被推薦。已在這塊白板上的卡片一律排除。
# 文獻：被板上卡片引用、還沒放上這塊白板者。
# @depends-on types.ts::BoardRecommendations / BoardRecommend.tsx / db.py::tags(axis, parent_id)、card_tags、card_literature、board_literatures
# assumption: card_tags 全表可一次讀入記憶體（個人使用規模）；if broken: 變慢，不會算錯
@router.get("/boards/{board_id}/recommendations")
def get_board_recommendations(board_id: str, request: Request, limit: int = Query(30, ge=1, le=100)):
    with session(request, write=False) as conn:
        _board(conn, board_id)
        on_board = {r["card_id"] for r in conn.execute("SELECT card_id FROM board_cards WHERE board_id = ?", (board_id,))}
        # 相關白板上的卡片也是候選；已在這塊白板上的卡片永遠不推薦
        related = _related_boards(conn, board_id)
        rel_cards: dict[str, list[dict]] = {}
        if related:
            rmarks = ",".join("?" * len(related))
            for r in conn.execute(
                f"SELECT card_id, board_id FROM board_cards WHERE board_id IN ({rmarks})", list(related)
            ):
                if r["card_id"] not in on_board:
                    rel_cards.setdefault(r["card_id"], []).append(related[r["board_id"]])
        if not on_board and not rel_cards:
            return {"board_card_count": 0, "cards": [], "cards_total": 0, "literatures": []}

        tags = {r["id"]: r for r in conn.execute("SELECT id, name, axis, parent_id FROM tags")}
        chains: dict[str, list[str]] = {}

        def chain(tag_id: str) -> list[str]:
            """自己加上所有祖先（由近到遠）。"""
            if tag_id in chains:
                return chains[tag_id]
            out, seen, cur = [], set(), tag_id
            while cur is not None:
                if cur in seen:
                    raise AppError(ErrorCode.CYCLE_DETECTED, "標籤的上下層關係出現循環，資料異常", {"tag_id": tag_id})
                seen.add(cur)
                t = tags.get(cur)
                if t is None:
                    raise AppError(ErrorCode.NOT_FOUND, "標籤不存在", {"tag_id": cur})
                out.append(cur)
                cur = t["parent_id"]
            chains[tag_id] = out
            return out

        def is_location(tag_id: str) -> bool:
            return tags[tag_id]["axis"] in _LOCATION_AXES

        def expand(tag_ids) -> set[str]:
            s: set[str] = set()
            for tid in tag_ids:
                if tid not in tags:
                    raise AppError(ErrorCode.NOT_FOUND, "標籤不存在", {"tag_id": tid})
                s.update(chain(tid) if is_location(tid) else (tid,))
            return s

        by_card: dict[str, list[str]] = {}
        for r in conn.execute("SELECT card_id, tag_id FROM card_tags"):
            by_card.setdefault(r["card_id"], []).append(r["tag_id"])
        support: dict[str, int] = {}  # 標籤（位置含祖先）→ 板上有幾張卡片帶有它
        for cid in on_board:
            for tid in expand(by_card.get(cid, ())):
                support[tid] = support.get(tid, 0) + 1
        updated = {r["id"]: r["updated_at"] for r in conn.execute("SELECT id, updated_at FROM cards")}

        scored = []
        for cid in by_card.keys() | rel_cards.keys():
            if cid in on_board:
                continue
            shared = expand(by_card.get(cid, ())) & support.keys()
            near = cid in rel_cards
            if not shared and not near:
                continue
            covered = {a for t in shared if is_location(t) for a in chain(t)[1:]}  # 更深一層也吻合的祖先不重複列出
            keep = [t for t in shared if t not in covered]
            depth = sum(len(chain(t)) for t in keep if is_location(t))
            scored.append((1 if near else 0, len(keep), depth, sum(support[t] for t in keep), updated[cid], cid, keep))
        scored.sort(key=lambda s: s[:6], reverse=True)

        cards = []
        top = scored[:limit]
        if top:
            marks = ",".join("?" * len(top))
            rows = {
                r["id"]: r
                for r in conn.execute(
                    f"SELECT id, title, body, card_type, curation_status, updated_at FROM cards WHERE id IN ({marks})",
                    [s[5] for s in top],  # scored 的 tuple 第 4 格是 updated 時間、第 5 格才是 cid；原本用 s[4] 查不到任何卡片，rows[cid] 因而 KeyError
                )
            }
            for _near, _n, _depth, _sup, _upd, cid, keep in top:
                r = rows[cid]
                reasons = sorted(
                    (
                        {
                            "tag_id": t,
                            "label": " / ".join(tags[x]["name"] for x in reversed(chain(t))) if is_location(t) else tags[t]["name"],
                            "axis": tags[t]["axis"],
                            "support": support[t],
                        }
                        for t in keep
                    ),
                    key=lambda x: (x["axis"] not in _LOCATION_AXES, -x["support"], x["label"]),
                )
                cards.append(
                    {
                        "id": r["id"],
                        "title": r["title"],
                        "snippet": r["body"][:160],
                        "card_type": r["card_type"],
                        "curation_status": r["curation_status"],
                        "updated_at": r["updated_at"],
                        "reasons": reasons,
                        "related_boards": sorted(rel_cards.get(cid, []), key=lambda b: (b["kind"] != "tree", b["name"])),
                    }
                )

        literatures = conn.execute(
            """SELECT l.id, l.title, l.author, substr(l.body, 1, 160) AS snippet, l.updated_at,
                      COUNT(DISTINCT cl.card_id) AS cited_by
               FROM card_literature cl
               JOIN board_cards bc ON bc.card_id = cl.card_id AND bc.board_id = ?
               JOIN literature l ON l.id = cl.literature_id
