# 刪除白板（含問題白板）的唯一入口；全部在同一個交易內完成，任何一步失敗整個回滾。
# children：底下有問題白板時的處理。block（預設）擋下並列出；subtree 整支一起處理；
#   promote 只用於問題白板：子問題改掛到被刪問題的母白板（母畫布座標重新排開）。
# keep_record：封存而非永久刪除。只作用於問題白板（一般白板本身永遠是永久刪除，但 subtree 時它底下的問題可封存）。
#   封存的內容原封不動；已封存的問題只能永久刪除。
# 重送一次會得到 NOT_FOUND，不會重複處理。
# @depends-on db.py::BOARD_QUESTIONS_DDL（parent_board_id ON DELETE RESTRICT：刪白板前必須先清掉指向它的母子關係）
@router.delete("/boards/{board_id}")
def delete_board(
    board_id: str,
    request: Request,
    children: BoardChildrenMode = BoardChildrenMode.BLOCK,
    keep_record: bool = False,
    reason: str = Query("", max_length=500),
):
    reason = reason.strip()
    with session(request, write=True) as conn:
        _board(conn, board_id)
        q = _question_row(conn, board_id)
        is_archived = q is not None and q["archived_at"] is not None
        desc = _descendants(conn, board_id)
        direct = [d for d in desc if d["depth"] == 1]

        if desc and children == BoardChildrenMode.BLOCK:
            raise AppError(
                ErrorCode.IN_USE,
                f"這塊白板底下還有 {len(desc)} 個問題白板，請先處理它們",
                {"children": [{"id": d["id"], "name": d["name"]} for d in direct], "descendant_count": len(desc)},
            )
        if children == BoardChildrenMode.PROMOTE:
            if q is None:
                raise AppError(ErrorCode.VALIDATION_ERROR, "一般白板沒有上一層，無法把子問題提升一級")
            if is_archived:
                raise AppError(ErrorCode.INVALID_STATE, "已封存的問題不能提升子問題")
            if not direct:
                raise AppError(ErrorCode.VALIDATION_ERROR, "沒有子問題可以提升")
        if keep_record:
            if is_archived:
                raise AppError(ErrorCode.INVALID_STATE, "這個問題已經封存，只能永久刪除")
            if q is None and not (children == BoardChildrenMode.SUBTREE and desc):
                raise AppError(ErrorCode.VALIDATION_ERROR, "這次刪除沒有任何問題白板，沒有紀錄可保留")
        elif reason:
            raise AppError(ErrorCode.VALIDATION_ERROR, "沒有保留紀錄時不需要填刪除原因")

        now = utc_now()
        parent_id = q["parent_board_id"] if q else None
        subtree_ids = [d["id"] for d in desc] if children == BoardChildrenMode.SUBTREE else []

        promoted = 0
        if children == BoardChildrenMode.PROMOTE:
            # 子問題換母畫布後原座標不通用：從被刪節點的位置起橫向排開（不做碰撞避讓，之後自行拖曳）
            x = q["x"]
            for kid in conn.execute(
                "SELECT board_id, w FROM board_questions WHERE parent_board_id = ? ORDER BY created_at", (board_id,)
            ).fetchall():
                conn.execute(
                    "UPDATE board_questions SET parent_board_id = ?, x = ?, y = ? WHERE board_id = ?",
                    (parent_id, x, q["y"], kid["board_id"]),
                )
                x += kid["w"] + QUESTION_PROMOTE_GAP
                promoted += 1

        archived_ids = []
        if keep_record:
            # 封存根節點脫離母節點；後代仍指向各自的母節點，保留封存內部的結構。
            # 一般白板被刪時，它底下的第一層問題就是封存根節點。
            roots = [board_id] if q else [d["id"] for d in direct]
            archived_ids = ([board_id] if q else []) + subtree_ids
            paths = {rid: _path_names(conn, rid) for rid in roots}  # 路徑快照必須在切斷母節點之前取得
            marks = ",".join("?" * len(archived_ids))
            conn.execute(f"UPDATE board_questions SET archived_at = ? WHERE board_id IN ({marks})", [now, *archived_ids])
            for rid in roots:
                conn.execute(
                    "UPDATE board_questions SET parent_board_id = NULL, archive_reason = ?, archive_path = ? "
                    "WHERE board_id = ?",
                    (reason, paths[rid], rid),
                )
            delete_ids = [] if q else [board_id]
        else:
            delete_ids = [board_id, *subtree_ids]

        if delete_ids:
            marks = ",".join("?" * len(delete_ids))
            # 先清問題列再刪白板：RESTRICT 只允許刪掉「已經沒有人指向它」的白板
            conn.execute(f"DELETE FROM board_questions WHERE board_id IN ({marks})", delete_ids)
            conn.execute(f"DELETE FROM boards WHERE id IN ({marks})", delete_ids)  # 只連鎖刪白板自己的內容，不動卡片與文獻
        if parent_id is not None:
            conn.execute("UPDATE boards SET updated_at = ? WHERE id = ?", (now, parent_id))
        return {
            "deleted": True,
            "deleted_count": len(delete_ids),
            "archived_count": len(archived_ids),
            "promoted_count": promoted,
        }


