# 問題白板之間的人工關聯：獨立於 parent_board_id 的多對多層，不影響 get_question_page 的契約。
# 兩端可以是任何白板（含沒有問題列的一般白板、最上層母白板），但已封存的問題不能建立新關聯；已建立的關聯不因封存而消失，刪除則永遠允許（才能清掉過時的連結）。
# @depends-on db.py::QUESTION_RELATIONS_DDL（對稱類型 board_a < board_b、有方向類型 supports／extends 都由 CHECK 把關）
# @depends-on types.ts::QuestionRelation / QuestionNavigator.tsx（「相關」列）
# @depends-on cards.py::sync_export／sync_overwrite、schemas.SyncQuestionRelationItem（備份帶關聯；舊封包沒有此欄時覆蓋沿用本機的並回報 relations_pruned）
@router.get("/boards/{board_id}/relations")
def list_question_relations(board_id: str, request: Request):
    with session(request, write=False) as conn:
        _board(conn, board_id)
        rows = conn.execute(
            """SELECT r.id, r.board_a, r.relation_type, b.id AS other_id, b.name AS other_name, bq.archived_at
               FROM question_relations r
               JOIN boards b ON b.id = CASE WHEN r.board_a = ? THEN r.board_b ELSE r.board_a END
               LEFT JOIN board_questions bq ON bq.board_id = b.id
               WHERE r.board_a = ? OR r.board_b = ?
               ORDER BY r.created_at, r.id""",
            (board_id, board_id, board_id),
        ).fetchall()
        return {
            "relations": [
                {
                    "id": r["id"],
                    "other_board_id": r["other_id"],
                    "other_name": r["other_name"],
                    "relation_type": r["relation_type"],
                    "direction": (
                        ("outgoing" if r["board_a"] == board_id else "incoming")
                        if QuestionRelationType(r["relation_type"]) in QUESTION_DIRECTED_TYPES
                        else "symmetric"
                    ),
                    "archived": r["archived_at"] is not None,
                }
                for r in rows
            ]
        }


def _put_question_relation(conn, source_id, target_id, relation_type):
    """寫入一筆關聯，回傳 (id, existed)。單筆與批次共用這一個判定；任何拒絕都丟 AppError，由呼叫端的交易整批回滾。"""
    if source_id == target_id:
        raise AppError(ErrorCode.VALIDATION_ERROR, "問題不能和自己建立關聯", {"board_id": source_id})
    a, b = source_id, target_id
    # 對稱類型固定 a < b（與 DDL CHECK 同一個比較；id 是 ASCII uuid，Python 與 SQLite 的字串順序一致）
    if relation_type not in QUESTION_DIRECTED_TYPES and a > b:
        a, b = b, a
    for bid in (a, b):
        _board(conn, bid)
        q = _question_row(conn, bid)  # 一般白板沒有問題列（q 為 None），可以參與
        if q is not None and q["archived_at"] is not None:
            raise AppError(ErrorCode.INVALID_STATE, "已封存的問題不能建立新的關聯", {"board_id": bid})
    row = conn.execute(
        "SELECT id FROM question_relations WHERE board_a = ? AND board_b = ? AND relation_type = ?",
        (a, b, relation_type.value),
    ).fetchone()
    if row is not None:
        return row["id"], True
    rid = new_id()
    conn.execute(
        "INSERT INTO question_relations (id, board_a, board_b, relation_type, created_at) VALUES (?, ?, ?, ?, ?)",
        (rid, a, b, relation_type.value, utc_now()),
    )
    return rid, False


# 全部關聯（唯讀）：樹狀圖的節點標記與概念圖譜的白板網絡一次取用。已封存白板的關聯也在內，前端以 boards 清單過濾。
