@router.post("/question-relations/batch")
def create_question_relations_batch(payload: QuestionRelationBatchCreate, request: Request):
    """星狀批次建立：單一交易，全成功或全回滾（任何一個目標被拒絕就一筆都不寫）。已存在的回報 existed，重送安全。"""
    targets = list(dict.fromkeys(payload.target_board_ids))  # 去重並保留順序
    with session(request, write=True) as conn:
