            "SELECT 1 FROM board_cards WHERE board_id = ? AND card_id = ?", (board_id, payload.card_id)
        ).fetchone() is None:
            raise AppError(ErrorCode.NOT_FOUND, "卡片不在這塊白板上", {"card_id": payload.card_id})
        if conn.execute(
            "SELECT 1 FROM board_image_links WHERE image_id = ? AND card_id = ?", (payload.image_id, payload.card_id)
        ).fetchone():
            return {"existed": True}
        now = utc_now()
        conn.execute(
            "INSERT INTO board_image_links (image_id, card_id, created_at) VALUES (?, ?, ?)",
            (payload.image_id, payload.card_id, now),
        )
        conn.execute("UPDATE boards SET updated_at = ? WHERE id = ?", (now, board_id))
