                left: 0,
                right: 0,
                top: "calc(100% + 2px)",
                maxHeight: 280,
                overflowY: "auto",
                background: "var(--panel, #1e293b)",
                border: "1px solid var(--line, #475569)",
                borderRadius: 6,
                boxShadow: "0 6px 16px rgba(0, 0, 0, 0.38)",
                zIndex: 60,
