                            display: "flex",
                            alignItems: "center",
                            justifyContent: "space-between",
                            gap: 6,
                            padding: "5px 10px",
                            border: "none",
                            background: p.filter.tagId === t.id ? "var(--row-hover, rgba(59,130,246,0.15))" : "transparent",
                            color: "var(--text)",
                            fontSize: 12,
