          </button>
        </div>
        <div className="row nav-row">
          <button
            type="button"
            className="label"
            onClick={() => window.open(`${import.meta.env.BASE_URL}exam/index.html#import`, "cardnote-exam")}
            title="直接開啟匯入考卷頁面"
          >
            <Icon name="plus"/> 匯入考卷
          </button>
        </div>
      </section>

      <section>
        <div className="section-head">
          <h3>資料維護與同步</h3>
        </div>
        <div className="row">
          <button className="label" onClick={() => setSyncOpen(true)} aria-label="資料同步與備份">
            <Icon name="cloud" /> 同步／備份
          </button>
        </div>
        {getPreferredDriverType() !== "dexie" && (
          <div className="row">
            <button className="label" onClick={() => void openCleanup()} aria-label="清理孤兒媒體">
