      {syncOpen && (
        <SyncModal
          onClose={() => setSyncOpen(false)}
          onApplied={() => {
            p.onTagsChanged();
            p.onBoardsChanged();
          }}
          report={p.report}
          info={(text) => p.report(null, text)}
        />
      )}

      {deletingBoardId && (
        <BoardDeleteDialog
          boardId={deletingBoardId}
          onClose={() => setDeletingBoardId(null)}
          onDone={() => {
            setDeletingBoardId(null);
            p.onBoardsChanged();
          }}
          report={p.report}
        />
      )}
      {moving && <MoveDialog tag={moving} tags={p.tags} onCancel={() => setMoving(null)} onMove={(id) => void moveTag(moving, id)} />}
      {editingTag && (
        <TagMetaDialog
          tag={p.tags.find((x) => x.id === editingTag.id) ?? editingTag}
          onClose={() => setEditingTag(null)}
          onChanged={p.onTagsChanged}
          report={p.report}
        />
      )}
      {mergingTag && (
        <MergeTagDialog
          source={mergingTag}
          tags={p.tags}
          onClose={() => setMergingTag(null)}
          onMerged={() => {
            if (p.filter.tagId === mergingTag.id) p.onFilter({});
            setMergingTag(null);
            p.onTagsChanged();
          }}
          report={p.report}
        />
      )}
      {cleanup && (
        <CleanupDialog
