// 樣式選單用的符號：依選項順序對應原本 select 提示的順序；數量對不上就退回選項原文，不猜
const BULLET_GLYPHS = ["•", "◦", "▪", "▸", "✓"] as const;
const ORDERED_GLYPHS = ["1.", "(1)", "a.", "A.", "i."] as const;
function styleGlyph(glyphs: readonly string[], total: number, index: number, fallback: string): string {
  return glyphs.length === total ? glyphs[index] : fallback;
}

const STATUS_TEXT: Record<Status, string> = {
  saved: "已儲存",
  dirty: "未儲存",
  saving: "儲存中…",
  error: "儲存失敗",
  conflict: "版本衝突",
};

interface OutlineItem {
  id: string;
  title: string;
  level: number;
  lineIndex: number;
  kind: "heading" | "details";
}

function extractOutlineItems(body: string): OutlineItem[] {
  const lines = body.split("\n");
  const items: OutlineItem[] = [];
  // 代碼圍欄內的 # 與 <summary> 只是代碼文字，不是章節；與 splitBodySegments 共用同一份圍欄判定
  const fences = fencedRanges(body);
  let offset = 0;

  for (let i = 0; i < lines.length; i++) {
    const lineStart = offset;
    offset += lines[i].length + 1;
    if (fences.some(([a, b]) => lineStart >= a && lineStart < b)) continue;
    const line = lines[i].trim();
    const hMatch = line.match(/^(#{1,6})\s+(.*)$/);
    if (hMatch) {
      items.push({
        id: `h-${i}`,
        title: hMatch[2].trim(),
        level: hMatch[1].length,
        lineIndex: i,
        kind: "heading",
      });
      continue;
    }
    const sumMatch = line.match(/<summary>(.*?)<\/summary>/i);
    if (sumMatch) {
      const rawText = sumMatch[1].trim();
      const innerH = rawText.match(/^(#{1,6})\s+(.*)$/);
      items.push({
        id: `d-${i}`,
        title: innerH ? innerH[2].trim() : rawText,
        level: innerH ? innerH[1].length : 2,
        lineIndex: i,
        kind: "details",
      });
    }
  }
  return items;
}

function adjustOutlineLevel(body: string, item: OutlineItem, delta: 1 | -1): EditPatch | null {
  const lines = body.split("\n");
  if (item.lineIndex < 0 || item.lineIndex >= lines.length) return null;
  const line = lines[item.lineIndex];
  const nextLevel = Math.max(1, Math.min(6, item.level + delta));
  if (nextLevel === item.level) return null;

  let newLine = line;
  if (item.kind === "heading") {
    newLine = `${"#".repeat(nextLevel)} ${item.title}`;
  } else if (item.kind === "details") {
    newLine = `<summary>${"#".repeat(nextLevel)} ${item.title}</summary>`;
  }

  let lineOffset = 0;
  for (let i = 0; i < item.lineIndex; i++) {
    lineOffset += lines[i].length + 1;
  }

  const nextBody = body.slice(0, lineOffset) + newLine + body.slice(lineOffset + line.length);
  return {
    text: nextBody,
    selectionStart: lineOffset + newLine.length,
    selectionEnd: lineOffset + newLine.length,
    replaceFrom: lineOffset,
    replaceTo: lineOffset + line.length,
    insertText: newLine,
  };
}

const LINE_TYPE_BUTTONS: readonly { type: LineType; label: string }[] = [
  { type: "p", label: "段落" },
  { type: "h1", label: "標題 1" },
  { type: "h2", label: "標題 2" },
  { type: "h3", label: "標題 3" },
];

export function Editor({ card, save, allowMention = true, plainPaste = false, pasteTransform = transformPasteContent, compact = false, initialSmartPaste, onClearInitialSmartPaste, initialFind, onClearInitialFind, onSaved, onReload, onLinkAdded, onOpenCard, onDirtyChange, onReturnToBoard, report }: Props) {
  const [title, setTitle] = useState(card.title);
  const [body, setBody] = useState(() => normalizeNewlines(card.body));
  const [cursorPos, setCursorPos] = useState(0);
  const [previewing, setPreviewing] = useState(false);
  const [status, setStatus] = useState<Status>("saved");
  const [errorMsg, setErrorMsg] = useState("");
  const [uploading, setUploading] = useState(0);
  const [warnings, setWarnings] = useState(card.warnings);
  const [mentionState, setMentionState] = useState<{
    replaceFrom: number;
    replaceTo: number;
    initialQuery: string;
  } | null>(null);

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const [showScrollBottom, setShowScrollBottom] = useState(false);
  const [outlineOpen, setOutlineOpen] = useState(false);
  const [scrollbarDots, setScrollbarDots] = useState<{ id: string; topPercent: number; title: string; level: number }[]>([]);
  const [lineMenu, setLineMenu] = useState<{ segStart: number; lineTop: number; lineBottom: number } | null>(null);

  // 非 compact 時內文底部留出 35vh 空白：否則捲到底後，游標也無法被抬到視線中段
  const bottomPadVh = compact ? 0 : 35;

  const checkScrollBottom = useCallback(() => {
    const el = scrollContainerRef.current;
    if (!el) return;
    const diff = el.scrollHeight - el.scrollTop - el.clientHeight - (bottomPadVh * window.innerHeight) / 100;
    setShowScrollBottom(diff > 80);
  }, [bottomPadVh]);

  // @depends-on ./LiveSegmentEditor.tsx（CodeMirror 的 contenteditable；以瀏覽器 Selection 取得游標位置，不依賴 SegmentHandle）
  // 只在「打字造成的變動」呼叫：游標掉到捲動區 55% 以下時拉回 40% 高度；只往下捲，不把游標往上推
  const keepCaretComfortable = useCallback(() => {
    const box = scrollContainerRef.current;
    const sel = window.getSelection();
    if (!box || !sel || sel.rangeCount === 0 || !sel.isCollapsed) return;
    const range = sel.getRangeAt(0);
    if (!box.contains(range.startContainer)) return;
    const rects = range.getClientRects();
    const host =
      range.startContainer instanceof Element ? range.startContainer : range.startContainer.parentElement;
    const rect = rects.length > 0 ? rects[0] : host?.getBoundingClientRect();
    // 拿不到可信座標（全 0 或高度異常大＝量到整個容器）就不動，不猜
    if (!rect || (rect.top === 0 && rect.height === 0) || rect.height > 80) return;
    const b = box.getBoundingClientRect();
    const caretY = rect.top + rect.height / 2 - b.top;
    if (caretY > b.height * 0.55) {
      box.scrollTop += caretY - b.height * 0.4;
    }
  }, []);

  const scrollToBottom = useCallback(() => {
    const el = scrollContainerRef.current;
    if (!el) return;
    el.scrollTo({ top: el.scrollHeight, behavior: "smooth" });
  }, []);

  const updateScrollbarDots = useCallback(() => {
    const box = scrollContainerRef.current;
    if (!box) return;
    const totalHeight = box.scrollHeight;
    if (totalHeight <= 0) return;

    const headingEls = box.querySelectorAll<HTMLElement>("h1, h2, h3, h4, h5, h6, summary, .md-details-summary");
    const dots: { id: string; topPercent: number; title: string; level: number }[] = [];

    headingEls.forEach((el, idx) => {
      if (el.offsetParent === null && el.offsetHeight === 0) return;
      const topPercent = Math.min(98, Math.max(2, (el.offsetTop / totalHeight) * 100));
      const text = (el.textContent || "").trim().slice(0, 40);
      const tagName = el.tagName.toLowerCase();
      const level = tagName.startsWith("h") ? parseInt(tagName[1], 10) : 2;

      dots.push({
        id: `dot-${idx}-${el.offsetTop}`,
        topPercent,
        title: text || `標題 #${idx + 1}`,
        level,
      });
    });

    setScrollbarDots(dots);
  }, []);

  useEffect(() => {
    checkScrollBottom();
    const t = setTimeout(updateScrollbarDots, 120);
    return () => clearTimeout(t);
  }, [body, previewing, checkScrollBottom, updateScrollbarDots]);

  useEffect(() => {
    if (!lineMenu) return;
    const onDown = (e: MouseEvent) => {
      const target = e.target as HTMLElement | null;
      if (target?.closest(".floating-line-toolbar") || target?.closest(".line-gutter-btn")) return;
      setLineMenu(null);
    };
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") setLineMenu(null);
    };
    window.addEventListener("mousedown", onDown);
    window.addEventListener("keydown", onKey);
    return () => {
      window.removeEventListener("mousedown", onDown);
      window.removeEventListener("keydown", onKey);
    };
  }, [lineMenu]);

  const versionRef = useRef(card.updated_at);
  const latest = useRef({ title: card.title, body: normalizeNewlines(card.body) });
  const savingRef = useRef(false);
  const pendingRef = useRef(false);
  const textRef = useRef<SegmentHandle | null>(null);
  const statusRef = useRef<Status>("saved");
  statusRef.current = status;

  const markDirty = () => setStatus((s) => (s === "conflict" ? s : "dirty"));

  const saveRef = useRef<(() => Promise<void>) | undefined>(undefined);
  saveRef.current = async () => {
    if (savingRef.current) {
      pendingRef.current = true;
      return;
    }
    savingRef.current = true;
    setStatus("saving");
    const snap = { ...latest.current };
    try {
      const updated = save ? await save(snap, versionRef.current) : await api.patchCard(card.id, snap, versionRef.current);
      versionRef.current = updated.updated_at;
      setWarnings(updated.warnings);
      onSaved(updated);
      const unchanged = latest.current.title === snap.title && latest.current.body === snap.body;
      setStatus(unchanged ? "saved" : "dirty");
    } catch (e) {
      if (e instanceof ApiError && e.code === "STALE_VERSION") setStatus("conflict");
      else {
        setStatus("error");
        setErrorMsg(messageOf(e));
      }
      pendingRef.current = false;
    } finally {
      savingRef.current = false;
      if (pendingRef.current) {
        pendingRef.current = false;
        void saveRef.current?.();
      }
    }
  };

  useEffect(() => {
    if (status !== "dirty" || uploading > 0) return;
    const t = setTimeout(() => void saveRef.current?.(), 1000);
    return () => clearTimeout(t);
  }, [title, body, status, uploading]);

  // 元件卸載（例如在白板結束內嵌編輯或切換卡片）時，若仍有未儲存變更則立即沖刷存檔
  useEffect(() => {
    return () => {
      if (statusRef.current === "dirty" && !savingRef.current) {
        void saveRef.current?.();
      }
    };
  }, []);

  // 讓外層（檔案連動列）知道目前畫面上的內文是否已存進資料庫
  useEffect(() => {
    onDirtyChange?.(status !== "saved" || uploading > 0);
  }, [status, uploading, onDirtyChange]);

  useEffect(() => {
    const unsafe = status !== "saved" || uploading > 0;
    if (!unsafe) return;
    const h = (e: BeforeUnloadEvent) => {
      e.preventDefault();
      e.returnValue = "";
    };
    window.addEventListener("beforeunload", h);
    return () => window.removeEventListener("beforeunload", h);
  }, [status, uploading]);

  const onTitle = (v: string) => {
    latest.current.title = v;
    setTitle(v);
    markDirty();
  };
  const onBody = (v: string) => {
    latest.current.body = v;
    setBody(v);
    markDirty();
  };

  const segRefs = useRef<Map<number, SegmentHandle>>(new Map());

  const getGlobalSelection = (): { start: number; end: number } => {
    // 目前段落若已被移除（例如刪掉圖片後前後段落合併），退回第一段，不讀已銷毀的 view
    let h = textRef.current;
    if (!h || !h.alive) h = segRefs.current.get(0) ?? null;
    if (!h) return { start: cursorPos, end: cursorPos };
    const sel = h.getSelection();
    return { start: h.start + sel.from, end: h.start + sel.to };
  };

  // 依「整份 body 的全域位置」找到對應段落並放置選取
  const placeSelection = useCallback((text: string, from: number, to: number) => {
    for (const s of splitBodySegments(text)) {
      // 一般文字段與收摺章節的內文都是可編輯區間；圖片不是
      const segStart = s.kind === "text" ? s.start : s.kind === "details" ? s.contentStart : -1;
      const segEnd = s.kind === "text" ? s.end : s.kind === "details" ? s.contentEnd : -1;
      if (segStart >= 0 && from >= segStart && from <= segEnd) {
        const h = segRefs.current.get(segStart);
        if (h) {
          textRef.current = h;
          const localStart = Math.max(0, from - segStart);
          const localEnd = Math.max(localStart, Math.min(segEnd - segStart, to - segStart));
          h.focus();
          h.setSelection(localStart, localEnd);
        }
        return;
      }
    }
  }, []);

  const applyEditPatch = useCallback(
    (patch: EditPatch) => {
      onBody(patch.text);
      setCursorPos(patch.selectionStart);
      // 新內容要等 React 提交後才由 LiveSegmentEditor 同步進 view，所以選取等下一個 frame 再放
      requestAnimationFrame(() => placeSelection(patch.text, patch.selectionStart, patch.selectionEnd));
    },
    [placeSelection],
  );

  // ---- 全文尋找：在整份 body 裡找，所以 CodeMirror 沒渲染到的行也找得到；標示只改外觀，不改文件 ----
  const [findOpen, setFindOpen] = useState(false);
  const [findQuery, setFindQuery] = useState("");
  const [findIdx, setFindIdx] = useState(0);
  const findInputRef = useRef<HTMLInputElement>(null);
  const findMatches = useMemo(() => (findOpen ? findInBody(body, findQuery) : []), [findOpen, body, findQuery]);
  const findCur = findMatches.length ? Math.min(findIdx, findMatches.length - 1) : -1;

  // 只捲動，不選取、不搶焦點：輸入框裡連按 Enter 才能連續找下一個，也不會有任何字被誤蓋掉
  const revealAt = useCallback((globalPos: number) => {
    for (const s of splitBodySegments(latest.current.body)) {
      if (s.kind === "text" && globalPos >= s.start && globalPos <= s.end) {
        segRefs.current.get(s.start)?.reveal(globalPos - s.start);
        return;
      }
    }
  }, []);

  const openFind = () => {
    const { start, end } = getGlobalSelection();
    const picked = latest.current.body.slice(start, end);
    if (picked && picked.length <= 200 && !picked.includes("\n")) {
      const hits = findInBody(latest.current.body, picked);
      const first = Math.max(0, hits.findIndex((h) => h >= start));
      setFindQuery(picked);
      setFindIdx(first);
      if (hits.length) requestAnimationFrame(() => revealAt(hits[first]));
    }
    setFindOpen(true);
    requestAnimationFrame(() => {
      findInputRef.current?.focus();
      findInputRef.current?.select();
    });
  };

  const changeFindQuery = (v: string) => {
    setFindQuery(v);
    setFindIdx(0);
    const hits = findInBody(latest.current.body, v);
    if (hits.length) revealAt(hits[0]);
  };

  const stepFind = (dir: 1 | -1) => {
    if (findMatches.length === 0) return;
    const next = (findCur + dir + findMatches.length) % findMatches.length;
    setFindIdx(next);
    revealAt(findMatches[next]);
  };

  const closeFind = () => {
    setFindOpen(false);
    textRef.current?.focus();
  };

  useEffect(() => {
    if (!initialFind) return;
    setFindQuery(initialFind);
    setFindIdx(0);
    setFindOpen(true);
    const hits = findInBody(latest.current.body, initialFind);
    if (hits.length) requestAnimationFrame(() => revealAt(hits[0]));
    onClearInitialFind?.();
  }, [initialFind]);

  // 預覽模式整篇都在 DOM 裡，瀏覽器原生 Ctrl+F 就搜得到，所以不攔截
  const onEditorKeyDown = (e: React.KeyboardEvent) => {
    if (previewing || e.nativeEvent.isComposing) return;
    if ((e.ctrlKey || e.metaKey) && !e.shiftKey && !e.altKey && e.key.toLowerCase() === "f") {
      e.preventDefault();
      if (e.target === findInputRef.current) findInputRef.current?.select();
      else openFind();
    }
  };

  const [bulletStyle, setBulletStyle] = useState<BulletStyle>("dash");
  const [orderedStyle, setOrderedStyle] = useState<OrderedStyle>("decimal");
  const [highlightColor, setHighlightColor] = useState<HighlightColor>("amber");

  const handleToolbarLineType = (
    targetType: LineType,
    styleOpts?: { bulletStyle?: BulletStyle; orderedStyle?: OrderedStyle },
  ) => {
    const { start: selStart, end: selEnd } = getGlobalSelection();
    const patch = applyLineType(latest.current.body, selStart, selEnd, targetType, styleOpts);
    applyEditPatch(patch);
  };

  const handleToolbarInlineWrap = (marker: "**" | "++", placeholder: string) => {
    const { start: selStart, end: selEnd } = getGlobalSelection();
    const patch = applyInlineWrap(latest.current.body, selStart, selEnd, marker, placeholder);
    applyEditPatch(patch);
  };

  const handleToolbarHighlight = (color: HighlightColor | null) => {
    const { start: selStart, end: selEnd } = getGlobalSelection();
    if (color) setHighlightColor(color);
    const patch = applyHighlight(latest.current.body, selStart, selEnd, color);
    if (patch) applyEditPatch(patch);
  };

  const handleToolbarIndent = (direction: 1 | -1) => {
    const { start: selStart, end: selEnd } = getGlobalSelection();
    const patch = indentListLines(latest.current.body, selStart, selEnd, direction);
    if (patch) applyEditPatch(patch);
  };

  const handleToolbarFoldSection = () => {
    const { start: selStart, end: selEnd } = getGlobalSelection();
    const cur = latest.current.body;
    const selected = cur.slice(selStart, selEnd).trim();

    let summary = "章節標題";
    let content = selected;

    if (selected) {
      const lines = selected.split("\n");
      const firstLine = lines[0].trim();
      const cleanFirst = firstLine.replace(/^#{1,6}\s+/, "").replace(/^[*-]\s+/, "").trim();
      if (cleanFirst) {
        const headingMatch = firstLine.match(/^(#{1,6})/);
        summary = headingMatch ? `${headingMatch[1]} ${cleanFirst}` : cleanFirst;
        content = lines.slice(1).join("\n").trim();
      }
    }

    const prefix = selStart > 0 && cur[selStart - 1] !== "\n" ? "\n\n" : "";
    const suffix = selEnd < cur.length && cur[selEnd] !== "\n" ? "\n\n" : "\n";
    const block = `${prefix}<details open>\n<summary>${summary}</summary>\n\n${content || "在此輸入段落內容…"}\n</details>${suffix}`;

    const nextBody = cur.slice(0, selStart) + block + cur.slice(selEnd);
    const newCursor = selStart + block.length;

    applyEditPatch({
      text: nextBody,
      selectionStart: newCursor,
      selectionEnd: newCursor,
      replaceFrom: selStart,
      replaceTo: selEnd,
      insertText: block,
    });
  };

  const openMentionFromToolbar = () => {
    const { start, end } = getGlobalSelection();
    setMentionState({ replaceFrom: start, replaceTo: end, initialQuery: "" });
  };

  const handleSelectMention = async (target: { id: string; title: string }) => {
    if (!mentionState) return;
    try {
      const link = await api.putLink(card.id, target.id, {
        relation_type: "延伸",
        status: "confirmed",
        reason: "",
      });
      const refMarkdown = formatCardRef(target.id, target.title);
      const curBody = latest.current.body;
      const from = Math.max(0, Math.min(curBody.length, mentionState.replaceFrom));
      const to = Math.max(from, Math.min(curBody.length, mentionState.replaceTo));
      const nextText = curBody.slice(0, from) + refMarkdown + curBody.slice(to);
      const nextCursor = from + refMarkdown.length;

      setMentionState(null);
      applyEditPatch({
        text: nextText,
        selectionStart: nextCursor,
        selectionEnd: nextCursor,
        replaceFrom: from,
        replaceTo: to,
        insertText: refMarkdown,
      });
      onLinkAdded?.(card.id, target.id, link);
    } catch (e) {
      report(e, "建立引用連結失敗");
    }
  };

  const uploadFiles = async (files: File[], at: number) => {
    setUploading((n) => n + files.length);
    let cursor = at;
    for (const f of files) {
      try {
        const info = await api.uploadMedia(f);
        const r = insertAtCursor(latest.current.body, cursor, cursor, mediaRef(info.id) + "\n");
        cursor = r.cursor;
        onBody(r.text);
        requestAnimationFrame(() => placeSelection(r.text, r.cursor, r.cursor));
      } catch (e) {
        report(e, `上傳「${f.name}」失敗，未插入任何內容`);
      } finally {
        setUploading((n) => n - 1);
      }
    }
  };

  const takeFiles = (list: FileList | null | undefined): File[] => {
    const all = Array.from(list ?? []);
    if (!all.length) return [];
    const ok = all.filter((f) => isAcceptedMime(f.type));
    if (ok.length < all.length) {
      report(new Error("支援 PNG／JPEG／WebP／GIF 圖片與 MP4／WebM 影片"), "已略過不支援的檔案");
    }
    return ok;
  };

  const copyMine = useCallback(async () => {
    try {
      await navigator.clipboard.writeText(`${latest.current.title}\n\n${latest.current.body}`);
    } catch (e) {
      report(e, "複製失敗");
    }
  }, [report]);

  const [codePatchOpen, setCodePatchOpen] = useState(() => Boolean(initialSmartPaste));

  useEffect(() => {
    if (initialSmartPaste) {
      setCodePatchOpen(true);
    }
  }, [initialSmartPaste]);

  // 取代成功且卡片綁定了本機檔案時詢問是否寫檔；null＝不顯示
  const [filePrompt, setFilePrompt] = useState<{ writing: boolean; result: string | null } | null>(null);

  // 原因：取代後內文是 dirty，要等 1 秒自動存檔計時才會 saved，這段時間寫檔按鈕是 disabled，
  // 使用者按下去會被吞掉。彈窗開著時改成立刻存檔；saveRef 內已有 savingRef 防重入，不會重複存。
  useEffect(() => {
    if (filePrompt && status === "dirty" && uploading === 0) void saveRef.current?.();
  }, [filePrompt, status, uploading]);

  const writeBoundFile = async (force = false): Promise<void> => {
    setFilePrompt({ writing: true, result: null });
    try {
      // 後端寫的是資料庫裡的內文；按鈕只在 status 為 saved 時可按，此時 versionRef 就是資料庫版本
      const res = await api.writeCardFile(card.id, { expected_updated_at: versionRef.current, force });
      setFilePrompt({
        writing: false,
        result: `✓ ${res.message}${res.has_backup ? "（已於 cardboard_backups 保留備份）" : ""}`,
      });
    } catch (e) {
      if (e instanceof ApiError && e.code === "FILE_CONFLICT") {
        if (window.confirm(`⚠️ ${e.message}\n\n是否仍要強制覆寫？`)) {
          await writeBoundFile(true);
          return;
        }
        setFilePrompt({ writing: false, result: null });
        return;
      }
      setFilePrompt({ writing: false, result: null });
      report(e, "寫入檔案失敗");
    }
  };

  const insertCodeBlock = () => {
    const label = window.prompt("輸入代碼塊名稱或檔名（例如 Board.tsx，可留空）", "");
    if (label === null) return;
    const cleanLabel = label.trim().replace(/\s+/g, "_");
    const extIdx = cleanLabel.lastIndexOf(".");
    const ext = extIdx >= 0 ? cleanLabel.slice(extIdx + 1).toLowerCase() : "tsx";
    const lang = ext || "tsx";
    const header = cleanLabel ? "```" + lang + ":" + cleanLabel : "```" + lang;

    const cur = latest.current.body;
    const { start: from, end: to } = getGlobalSelection();
    const selectedText = cur.slice(from, to);
    const prefixNewline = from > 0 && cur[from - 1] !== "\n" ? "\n\n" : "";
    const insertText = prefixNewline + header + "\n" + selectedText + "\n```\n";
    const nextText = cur.slice(0, from) + insertText + cur.slice(to);
    const cursorInside = from + prefixNewline.length + header.length + 1 + selectedText.length;

    applyEditPatch({
      text: nextText,
      selectionStart: cursorInside,
      selectionEnd: cursorInside,
      replaceFrom: from,
      replaceTo: to,
      insertText,
    });
  };

  const insertTable = (cols: number, rows: number) => {
    const cur = latest.current.body;
    const { start: from, end: to } = getGlobalSelection();
    const tableMarkdown = createMarkdownTable(cols, rows);
    const prefixNewline = from > 0 && cur[from - 1] !== "\n" ? "\n\n" : "";
    const suffixNewline = to < cur.length && cur[to] !== "\n" ? "\n\n" : "\n";
    const insertText = prefixNewline + tableMarkdown + suffixNewline;
    const nextText = cur.slice(0, from) + insertText + cur.slice(to);
    const cursorInside = from + prefixNewline.length + tableMarkdown.length;
    applyEditPatch({
      text: nextText,
      selectionStart: cursorInside,
      selectionEnd: cursorInside,
      replaceFrom: from,
      replaceTo: to,
      insertText,
    });
  };

  const handleTableAction = (action: "addRow" | "deleteRow" | "addCol" | "deleteCol" | "deleteTable") => {
    const cur = latest.current.body;
    const { start: selStart } = getGlobalSelection();
    const info = detectTableAtCursor(cur, selStart);
    if (!info) return;
    const patch = modifyMarkdownTable(cur, info, action);
    if (patch) {
      applyEditPatch(patch);
    }
  };

  const currentLineType = detectLineType(body, cursorPos);
  const currentListStyle = detectListStyleAtCursor(body, cursorPos);
  const activeBulletStyle = currentListStyle.bulletStyle ?? bulletStyle;
  const activeOrderedStyle = currentListStyle.orderedStyle ?? orderedStyle;

  const missingMediaCount = warnings
    .filter((w) => w.code === "MISSING_MEDIA")
    .reduce((n, w) => n + w.ids.length, 0);
  const missingCardCount = warnings
    .filter((w) => w.code === "MISSING_CARD")
    .reduce((n, w) => n + w.ids.length, 0);

  const [openMenu, setOpenMenu] = useState<"bullet" | "ordered" | null>(null);
  const [tablePickerOpen, setTablePickerOpen] = useState(false);

  // 反白圖標列：位置由 LiveSegmentEditor 回報；停頓 150ms 才顯示（拖曳選取時不閃爍），收合或失焦立即隱藏
  const [selBubble, setSelBubble] = useState<{ segStart: number; left: number; top: number } | null>(null);
  const selTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const selPendingSegRef = useRef<number | null>(null);

  // 反白圖標列的實際位置：要等它渲染後量到真實寬高才算得出來（假設固定寬度會讓左側被裁掉）
  const bubbleRef = useRef<HTMLDivElement>(null);
  const [bubblePos, setBubblePos] = useState<{ left: number; top: number } | null>(null);
  useLayoutEffect(() => {
    const el = bubbleRef.current;
    const parent = el?.offsetParent;
    if (!selBubble || !el || !(parent instanceof HTMLElement)) {
      setBubblePos(null);
      return;
    }
    const boxW = scrollContainerRef.current?.clientWidth ?? parent.clientWidth;
    const left = Math.max(8, Math.min(selBubble.left - el.offsetWidth / 2, boxW - el.offsetWidth - 8));
    // 預設放在反白範圍下方（沿用回報的位置）；上方放得下就改放上方，不蓋住往下延伸選取的文字
    let top = selBubble.top + 6;
    const sel = window.getSelection();
    const first = sel && sel.rangeCount > 0 && !sel.isCollapsed ? sel.getRangeAt(0).getClientRects()[0] : undefined;
    const box = scrollContainerRef.current?.getBoundingClientRect();
    if (first && first.height > 0 && box && first.top - box.top >= el.offsetHeight + 12) {
      top = first.top - parent.getBoundingClientRect().top - parent.clientTop - el.offsetHeight - 6;
    }
    setBubblePos({ left, top });
  }, [selBubble, lineMenu]);

  const reportSelectionRect = useCallback((segStart: number, rect: { left: number; bottom: number } | null) => {
    if (!rect) {
      // 只清掉「自己段落」的待顯示與已顯示；別的段落剛接手時，舊段落的失焦回報不能蓋掉它
      if (selPendingSegRef.current === segStart && selTimerRef.current) {
        clearTimeout(selTimerRef.current);
        selTimerRef.current = null;
        selPendingSegRef.current = null;
      }
      setSelBubble((cur) => (cur && cur.segStart === segStart ? null : cur));
      return;
    }
    if (selTimerRef.current) clearTimeout(selTimerRef.current);
    selPendingSegRef.current = segStart;
    selTimerRef.current = setTimeout(() => {
      selTimerRef.current = null;
      selPendingSegRef.current = null;
      setSelBubble({ segStart, left: rect.left, top: rect.bottom });
    }, 150);
  }, []);

  useEffect(
    () => () => {
      if (selTimerRef.current) clearTimeout(selTimerRef.current);
    },
    [],
  );

  // 切換預覽會銷毀所有 view（不會回報 null），回到編輯時不可殘留舊位置
  useEffect(() => {
    setSelBubble(null);
  }, [previewing]);

  const bubbleBtnStyle: React.CSSProperties = {
    width: 26,
    height: 26,
    padding: 0,
    display: "inline-flex",
    alignItems: "center",
    justifyContent: "center",
    fontSize: 14,
  };

  // 浮動工具列開關時，子選單一律回到收合
  useEffect(() => {
    setOpenMenu(null);
  }, [lineMenu]);

  // 點到分割按鈕以外的地方就收起子選單（工具列本身的關閉邏輯仍由 lineMenu 的 effect 負責）
  useEffect(() => {
    if (!openMenu) return;
    const onDown = (e: MouseEvent) => {
      if (!(e.target as HTMLElement | null)?.closest("[data-split]")) setOpenMenu(null);
    };
    window.addEventListener("mousedown", onDown);
    return () => window.removeEventListener("mousedown", onDown);
  }, [openMenu]);

  useEffect(() => {
    if (!tablePickerOpen) return;
    const onDown = (e: MouseEvent) => {
      const target = e.target as HTMLElement | null;
      if (!target?.closest("[data-table-picker]") && !target?.closest("[data-table-btn]")) {
        setTablePickerOpen(false);
      }
    };
    window.addEventListener("mousedown", onDown);
    return () => window.removeEventListener("mousedown", onDown);
  }, [tablePickerOpen]);

  const activeBulletMeta = BULLET_STYLE_OPTIONS.find((o) => o.style === activeBulletStyle);
  const activeOrderedMeta = ORDERED_STYLE_OPTIONS.find((o) => o.style === activeOrderedStyle);


  // 反白圖標列一消失就收起子選單，下次出現不會殘留展開狀態
  useEffect(() => {
    if (!selBubble) setOpenMenu(null);
  }, [selBubble]);

  // 行首 `::` 面板與反白圖標列共用：改這一份，兩邊同步
  const renderListSplits = () => (
    <>
      <SplitMenuButton
        open={openMenu === "bullet"}
        onToggle={() => setOpenMenu((m) => (m === "bullet" ? null : "bullet"))}
        main={<BulletListIcon />}
        mainTitle={`套用或取消項目符號（目前：${activeBulletMeta?.label ?? ""}）`}
        mainActive={currentLineType === "ul"}
        menuLabel="選擇項目符號樣式"
        onMain={() => handleToolbarLineType("ul", { bulletStyle: activeBulletStyle })}
      >
        {BULLET_STYLE_OPTIONS.map((o, i) => (
          <button
            key={o.style}
            type="button"
            role="menuitemradio"
            aria-checked={activeBulletStyle === o.style}
            aria-label={o.label}
            title={o.label}
            className={activeBulletStyle === o.style ? "on" : ""}
            style={{ minWidth: 28 }}
            onClick={() => {
              setBulletStyle(o.style);
              setOpenMenu(null);
              handleToolbarLineType("ul", { bulletStyle: o.style });
            }}
          >
            {styleGlyph(BULLET_GLYPHS, BULLET_STYLE_OPTIONS.length, i, o.label)}
          </button>
        ))}
      </SplitMenuButton>

      <SplitMenuButton
        open={openMenu === "ordered"}
        onToggle={() => setOpenMenu((m) => (m === "ordered" ? null : "ordered"))}
        main={<NumberedListIcon />}
        mainTitle={`套用或取消編號清單（目前：${activeOrderedMeta?.label ?? ""}）`}
        mainActive={currentLineType === "ol"}
        menuLabel="選擇編號清單樣式"
        onMain={() => handleToolbarLineType("ol", { orderedStyle: activeOrderedStyle })}
      >
        {ORDERED_STYLE_OPTIONS.map((o, i) => (
          <button
            key={o.style}
            type="button"
            role="menuitemradio"
            aria-checked={activeOrderedStyle === o.style}
            aria-label={o.label}
            title={o.label}
            className={activeOrderedStyle === o.style ? "on" : ""}
            style={{ minWidth: 28 }}
            onClick={() => {
              setOrderedStyle(o.style);
              setOpenMenu(null);
              handleToolbarLineType("ol", { orderedStyle: o.style });
            }}
          >
            {styleGlyph(ORDERED_GLYPHS, ORDERED_STYLE_OPTIONS.length, i, o.label)}
          </button>
        ))}
      </SplitMenuButton>
    </>
  );

  // 螢光筆色點＋移除；沒有反白時整排變灰不能點，不假裝成功
  const renderHighlightDots = (enabled: boolean) => (
    <>
      {HIGHLIGHT_COLOR_OPTIONS.map((c) => (
        <button
          key={c.color}
          type="button"
          disabled={!enabled}
          aria-label={`螢光筆：${c.label}`}
          title={enabled ? `螢光筆：${c.label}` : "先反白要上色的文字"}
          onClick={() => handleToolbarHighlight(c.color)}
          style={{
            width: 20,
            height: 20,
            padding: 0,
            borderRadius: "50%",
            background: c.dotColor,
