        </button>
        <button
          type="button"
          aria-label="減少縮排"
          title="減少縮排（Shift+Tab）"
          onClick={() => handleToolbarIndent(-1)}
          disabled={currentLineType !== "ul" && currentLineType !== "ol"}
        >
          ⇤
        </button>
      </span>

      <span role="group" aria-label="螢光筆顏色" style={{ display: "inline-flex", alignItems: "center", gap: 4 }}>
        {renderHighlightDots(lineMenuHasSelection)}
      </span>

      <span role="group" aria-label="插入" style={{ display: "inline-flex", alignItems: "center", gap: 4 }}>
        {allowMention && (
          <button type="button" onClick={openMentionFromToolbar}>
            @ 引用
          </button>
        )}
        <button type="button" onClick={insertCodeBlock} title="在卡片中插入可命名的代碼區塊">
          ＋ 代碼塊
        </button>
        <span style={{ position: "relative", display: "inline-flex" }}>
          <button
            type="button"
            data-table-btn
            className={detectTableAtCursor(latest.current.body, cursorPos) ? "on" : ""}
            onClick={() => setTablePickerOpen((o) => !o)}
            title="建立或管理表格（Word 式選取欄列）"
          >
            ⊞ 表格 ▾
          </button>
          <TableGridPicker
            open={tablePickerOpen}
            onClose={() => setTablePickerOpen(false)}
            onInsert={insertTable}
            inTable={Boolean(detectTableAtCursor(latest.current.body, cursorPos))}
            onAction={handleTableAction}
          />
        </span>
        {detectTableAtCursor(latest.current.body, cursorPos) && (
          <span role="group" aria-label="表格快捷" style={{ display: "inline-flex", alignItems: "center", gap: 2 }}>
            <button
              type="button"
              style={{ fontSize: 11, padding: "2px 6px" }}
              onClick={() => handleTableAction("addRow")}
              title="在下方增加一列"
            >
              ＋列
            </button>
            <button
              type="button"
              style={{ fontSize: 11, padding: "2px 6px" }}
              onClick={() => handleTableAction("deleteRow")}
              title="刪除游標所在列"
            >
              ➖列
            </button>
            <button
              type="button"
              style={{ fontSize: 11, padding: "2px 6px" }}
              onClick={() => handleTableAction("addCol")}
              title="在右側增加一欄"
            >
              ＋欄
            </button>
            <button
              type="button"
              style={{ fontSize: 11, padding: "2px 6px" }}
              onClick={() => handleTableAction("deleteCol")}
              title="刪除游標所在欄"
            >
              ➖欄
            </button>
          </span>
        )}
        <button
          type="button"
          onClick={handleToolbarFoldSection}
          title="將選取內容設定為可收摺章節"
        >
          📁 收摺章節
        </button>
        <button
          type="button"
          onClick={() => setCodePatchOpen(true)}
          title="對卡片內的代碼塊或外部代碼執行精確定位與自動取代"
        >
          定位取代
        </button>
      </span>
    </>
  );

  // 切換收摺／展開：只改開標籤，用實際的 ">" 位置界定，不假設標籤寫法（大小寫、空白）
  const toggleDetailsOpen = (seg: Extract<BodySegment, { kind: "details" }>) => {
    const cur = latest.current.body;
    const tagEnd = cur.indexOf(">", seg.rawStart) + 1;
    onBody(cur.slice(0, seg.rawStart) + (seg.isOpen ? "<details>" : "<details open>") + cur.slice(tagEnd));
  };

  // 解除收摺：整個區塊還原成「標題＋空行＋內文」的一般文字
  const unwrapDetailsSeg = (seg: Extract<BodySegment, { kind: "details" }>) => {
    const cur = latest.current.body;
    const unwrapped = seg.content ? `${seg.summary}\n\n${seg.content}` : seg.summary;
    applyEditPatch({
      text: cur.slice(0, seg.rawStart) + unwrapped + cur.slice(seg.rawEnd),
      selectionStart: seg.rawStart,
      selectionEnd: seg.rawStart + unwrapped.length,
      replaceFrom: seg.rawStart,
      replaceTo: seg.rawEnd,
      insertText: unwrapped,
    });
  };

  // 大綱跳轉：用內文位移定位，不比對畫面文字（編輯模式的 CodeMirror 不會渲染 h1~h6／summary 元素）
  const jumpToOutlineItem = (item: OutlineItem) => {
    const box = scrollContainerRef.current;
    if (!box) return;
    const cur = latest.current.body;
    const lines = cur.split("\n");
    let offset = 0;
    for (let i = 0; i < item.lineIndex && i < lines.length; i++) offset += lines[i].length + 1;

    const enclosing = splitBodySegments(cur).find(
      (s): s is Extract<BodySegment, { kind: "details" }> =>
        s.kind === "details" && offset >= s.rawStart && offset < s.rawEnd,
    );
    // 收摺章節本身，或位在已收摺章節內的標題：內文沒有渲染，只能捲到章節方塊
    if (enclosing && (item.kind === "details" || !enclosing.isOpen)) {
      box
        .querySelector<HTMLElement>(`[data-details-start="${enclosing.rawStart}"]`)
        ?.scrollIntoView({ behavior: "smooth", block: "start" });
      return;
    }

    placeSelection(cur, offset, offset);
    requestAnimationFrame(() => {
      const sel = window.getSelection();
      if (!sel || sel.rangeCount === 0) return;
      const range = sel.getRangeAt(0);
      const host =
        range.startContainer instanceof Element ? range.startContainer : range.startContainer.parentElement;
      const rect = range.getClientRects()[0] ?? host?.getBoundingClientRect();
      // 拿不到可信座標就不動，不猜
      if (!rect || (rect.top === 0 && rect.height === 0) || rect.height > 80) return;
      box.scrollTo({ top: box.scrollTop + rect.top - box.getBoundingClientRect().top - 24, behavior: "smooth" });
    });
  };

  // 收摺章節內文編輯器的事件；start 是該內文在整份 body 的全域起點（內容與一般文字段的處理相同）
  const detailsHandlers = (
    start: number,
  ): Pick<
    ComponentProps<typeof LiveSegmentEditor>,
    "onFocus" | "onSelectionChange" | "onSelectionRect" | "onToggleLineMenu" | "onDocChange" | "onKeyDown" | "onPaste" | "onDropFiles"
  > => ({
    onFocus: () => {
      const h = segRefs.current.get(start);
      if (h) textRef.current = h;
    },
    onSelectionChange: (from) => setCursorPos(start + from),
    onSelectionRect: (rect) => reportSelectionRect(start, rect),
    onToggleLineMenu: (rect) => {
      setLineMenu((cur) =>
        cur && cur.segStart === start && Math.abs(cur.lineTop - rect.lineTop) < 4
          ? null
          : { segStart: start, lineTop: rect.lineTop, lineBottom: rect.lineBottom },
      );
    },
    onDocChange: (val, prevLen, cursor) => {
      setLineMenu(null);
      const cur = latest.current.body;
      const prevBodyLen = cur.length;
      const nextBody = cur.slice(0, start) + val + cur.slice(start + prevLen);
      const globalPos = start + cursor;
      onBody(nextBody);
      setCursorPos(globalPos);
      requestAnimationFrame(keepCaretComfortable);
      if (allowMention && nextBody.length >= prevBodyLen && globalPos > 0 && nextBody[globalPos - 1] === "@") {
        const trig = detectAtTrigger(nextBody, globalPos);
        if (trig && trig.query === "") {
          setMentionState({ replaceFrom: trig.atIndex, replaceTo: globalPos, initialQuery: "" });
        }
      }
    },
    onKeyDown: (e, from, to) => {
      if (e.isComposing || e.keyCode === 229) return false;
      const gStart = start + from;
      const gEnd = start + to;
      if ((e.ctrlKey || e.metaKey) && !e.shiftKey && !e.altKey) {
        const k = e.key.toLowerCase();
        if (k === "b") {
          applyEditPatch(applyInlineWrap(latest.current.body, gStart, gEnd, "**", "粗體文字"));
          return true;
        }
        if (k === "u") {
          applyEditPatch(applyInlineWrap(latest.current.body, gStart, gEnd, "++", "底線文字"));
          return true;
        }
      }
      if (e.key === "Tab") {
        const patch = indentListLines(latest.current.body, gStart, gEnd, e.shiftKey ? -1 : 1);
        if (!patch) return false;
        applyEditPatch(patch);
        return true;
      }
      if (e.key === "Enter" && !e.shiftKey && !e.ctrlKey && !e.metaKey && !e.altKey) {
        const patch = handleListEnter(latest.current.body, gStart, gEnd);
        if (!patch) return false;
        applyEditPatch(patch);
        requestAnimationFrame(keepCaretComfortable);
        return true;
      }
      return false;
    },
    onPaste: (e, from, to) => {
      const cd = e.clipboardData;
      if (!cd) return false;
      const gFrom = start + from;
      const gTo = start + to;
      if (cd.files.length) {
        const files = takeFiles(cd.files);
        if (files.length) void uploadFiles(files, gFrom);
        return true;
      }
      if (plainPaste) return false;
      if (extractCodeBlocks(latest.current.body).some((b) => gFrom >= b.contentStart && gFrom <= b.contentEnd)) {
        return false;
      }
      const transformed = pasteTransform(cd.getData("text/plain"), cd.getData("text/html"));
      if (transformed === null) return false;
      const cur = latest.current.body;
      const nextCursor = gFrom + transformed.length;
      applyEditPatch({
        text: cur.slice(0, gFrom) + transformed + cur.slice(gTo),
        selectionStart: nextCursor,
        selectionEnd: nextCursor,
        replaceFrom: gFrom,
        replaceTo: gTo,
        insertText: transformed,
      });
      return true;
    },
    onDropFiles: (e, at) => {
      const dt = e.dataTransfer;
      if (!dt || !dt.files.length) return false;
      const files = takeFiles(dt.files);
      if (files.length) void uploadFiles(files, start + at);
      return true;
    },
  });

  return (
    <div className="editor" onKeyDown={onEditorKeyDown}>
      <div className="editor-head">
        <input
          className="title-input"
          value={title}
          placeholder="卡片標題"
          onChange={(e) => onTitle(e.target.value)}
          aria-label="卡片標題"
        />
        <span className={`status ${status}`} data-testid="save-status">
          {uploading > 0 ? `上傳中（${uploading}）…` : STATUS_TEXT[status]}
        </span>
        <button
          type="button"
          className={`preview-toggle-btn${previewing ? " on" : ""}`}
          style={{ fontSize: 11, padding: "2px 8px", marginLeft: 6 }}
          onClick={() => {
            setPreviewing((p) => {
              const next = !p;
              if (next) {
                setMentionState(null);
                setLineMenu(null);
              }
              return next;
            });
          }}
        >
          {previewing ? "✎ 返回編輯" : "👁 預覽"}
        </button>
        {!previewing && (
          <button
            type="button"
            className={findOpen ? "on" : ""}
            style={{ fontSize: 11, padding: "2px 8px", marginLeft: 6 }}
            onClick={() => (findOpen ? closeFind() : openFind())}
            title="在全文中尋找（Ctrl+F）"
          >
            🔍 尋找
          </button>
        )}
      </div>
      {status === "conflict" && (
        <div className="banner danger" role="alert">
          這張卡片已在別處被修改，你的修改尚未儲存。
          <button onClick={onReload}>重新載入（捨棄我的修改）</button>
          <button onClick={() => void copyMine()}>複製我的內容</button>
        </div>
      )}
      {status === "error" && (
        <div className="banner danger" role="alert">
          儲存失敗：{errorMsg}（內容仍保留在這裡）
          <button onClick={() => void saveRef.current?.()}>重試</button>
        </div>
      )}
      {missingMediaCount > 0 && (
        <div className="banner warn" role="alert">
          內文引用了 {missingMediaCount} 個不存在的媒體。
        </div>
      )}
      {missingCardCount > 0 && (
        <div className="banner warn" role="alert">
          內文引用了 {missingCardCount} 張不存在的卡片。
        </div>
      )}
      {findOpen && !previewing && (
        <div
          className="find-bar"
          role="search"
          style={{
            display: "flex",
            alignItems: "center",
            gap: 6,
            padding: "4px 8px",
            margin: "4px 0",
            border: "1px solid var(--line, #334155)",
            borderRadius: 6,
            background: "var(--panel, #1e293b)",
          }}
        >
          <input
            ref={findInputRef}
            value={findQuery}
            onChange={(e) => changeFindQuery(e.target.value)}
            onKeyDown={(e) => {
              if (e.nativeEvent.isComposing || e.keyCode === 229) return;
              if (e.key === "Enter") {
                e.preventDefault();
                stepFind(e.shiftKey ? -1 : 1);
              } else if (e.key === "Escape") {
                // 只關尋找列，不讓 Esc 冒泡到 App 把整個中央編輯關掉
                e.preventDefault();
                e.stopPropagation();
                closeFind();
              }
            }}
            placeholder="在全文中尋找（Enter 下一個，Shift+Enter 上一個）"
            aria-label="在全文中尋找"
            style={{ flex: 1, minWidth: 0 }}
          />
          <span className="muted" style={{ fontSize: 12, whiteSpace: "nowrap" }} aria-live="polite">
            {!findQuery ? "" : findMatches.length === 0 ? "找不到" : `${findCur + 1} / ${findMatches.length}`}
          </span>
          <button type="button" onClick={() => stepFind(-1)} disabled={findMatches.length === 0} aria-label="上一個" title="上一個（Shift+Enter）">
            ▲
          </button>
          <button type="button" onClick={() => stepFind(1)} disabled={findMatches.length === 0} aria-label="下一個" title="下一個（Enter）">
            ▼
          </button>
          <button type="button" onClick={closeFind} aria-label="關閉尋找" title="關閉（Esc）">
            ✕
          </button>
        </div>
      )}



      {!previewing && mentionState && (
        <MentionPopup
          currentCardId={card.id}
          initialQuery={mentionState.initialQuery}
          onSelect={handleSelectMention}
          onCancel={() => {
            setMentionState(null);
            textRef.current?.focus();
          }}
          report={report}
        />
      )}

      {codePatchOpen && createPortal(
        <CodeReplaceModal
          cardBody={body}
          cursorPos={cursorPos}
          initialSmartPaste={initialSmartPaste}
          onClose={() => {
            setCodePatchOpen(false);
            onClearInitialSmartPaste?.();
          }}
          onApplyPatch={(patch) => {
            applyEditPatch(patch);
            onClearInitialSmartPaste?.();
