                      onSelectionChange={(from) => setCursorPos(seg.start + from)}
                      onSelectionRect={(rect) => reportSelectionRect(seg.start, rect)}
                      onToggleLineMenu={(rect) => {
                        setLineMenu((cur) =>
                          cur && cur.segStart === seg.start && Math.abs(cur.lineTop - rect.lineTop) < 4
