                        if (!cd) return false;
                        const gFrom = seg.start + from;
                        const gTo = seg.start + to;
                        if (cd.files.length) {
                          const files = takeFiles(cd.files);
                          if (files.length) void uploadFiles(files, gFrom);
                          return true;
