// ---- 表格偵測、Word 式選取與行列智慧增減 ----

interface TableCursorInfo {
  tableStartOffset: number;
  tableEndOffset: number;
  lines: string[];
  currentRowIndex: number;
  currentColIndex: number;
}

function detectTableAtCursor(body: string, cursor: number): TableCursorInfo | null {
  if (!body) return null;
  const lines = body.split("\n");
  const lineStarts: number[] = [];
  let acc = 0;
  let targetLine = -1;

  for (let i = 0; i < lines.length; i++) {
    lineStarts.push(acc);
    const lineLen = lines[i].length;
    if (cursor >= acc && cursor <= acc + lineLen) {
      targetLine = i;
    }
    acc += lineLen + 1;
  }
  if (targetLine === -1) return null;

  const isTableRow = (s: string) => {
    const t = s.trim();
    return t.startsWith("|") && t.endsWith("|") && t.length >= 2;
  };

  if (!isTableRow(lines[targetLine])) return null;

  let startLine = targetLine;
  while (startLine > 0 && isTableRow(lines[startLine - 1])) {
    startLine--;
  }
  let endLine = targetLine;
  while (endLine < lines.length - 1 && isTableRow(lines[endLine + 1])) {
    endLine++;
  }

  const tableLines = lines.slice(startLine, endLine + 1);
  if (tableLines.length < 2) return null;

  const isSep = /^\s*\|(\s*:?-+:?\s*\|)+\s*$/.test(tableLines[1]);
  if (!isSep) return null;

  const tableStartOffset = lineStarts[startLine];
  const lastLineOffset = lineStarts[endLine];
  const tableEndOffset = lastLineOffset + lines[endLine].length;

  const currentRowIndex = targetLine - startLine;
  const curLineText = lines[targetLine];
  const cursorInLine = Math.max(0, cursor - lineStarts[targetLine]);
  const prefixWithoutEscapes = curLineText.slice(0, cursorInLine).replace(/\\\|/g, "");
  const pipeMatches = prefixWithoutEscapes.match(/\|/g);
  const currentColIndex = pipeMatches ? Math.max(0, pipeMatches.length - 1) : 0;

  return {
    tableStartOffset,
    tableEndOffset,
    lines: tableLines,
    currentRowIndex,
    currentColIndex,
  };
}

function createMarkdownTable(cols: number, rows: number): string {
  const c = Math.max(1, cols);
  const r = Math.max(2, rows);
  const header = "| " + Array.from({ length: c }, (_, i) => `標題 ${i + 1}`).join(" | ") + " |";
  const sep = "| " + Array.from({ length: c }, () => "---").join(" | ") + " |";
  const dataRows: string[] = [];
  for (let i = 0; i < r - 1; i++) {
    dataRows.push("| " + Array.from({ length: c }, () => "  ").join(" | ") + " |");
  }
  return [header, sep, ...dataRows].join("\n");
}

function modifyMarkdownTable(
  body: string,
  info: TableCursorInfo,
  action: "addRow" | "deleteRow" | "addCol" | "deleteCol" | "deleteTable",
): EditPatch | null {
  const { lines, currentRowIndex, currentColIndex, tableStartOffset, tableEndOffset } = info;
  if (action === "deleteTable") {
    const nextBody = body.slice(0, tableStartOffset) + body.slice(tableEndOffset);
    return {
      text: nextBody,
      selectionStart: tableStartOffset,
      selectionEnd: tableStartOffset,
      replaceFrom: tableStartOffset,
      replaceTo: tableEndOffset,
      insertText: "",
    };
  }

  const parseRow = (line: string) => {
    const trimmed = line.trim();
    if (!trimmed.startsWith("|") || !trimmed.endsWith("|")) return [];
    return trimmed.slice(1, -1).split("|").map((c) => c.trim());
  };
  const formatRow = (cells: string[]) => "| " + cells.map((c) => (c.length ? c : "  ")).join(" | ") + " |";

  const headerCells = parseRow(lines[0]);
  const colCount = Math.max(1, headerCells.length);
  const newLines = [...lines];

  if (action === "addRow") {
    const insertIdx = Math.max(2, currentRowIndex + 1);
    const newRow = formatRow(Array.from({ length: colCount }, () => "  "));
    newLines.splice(insertIdx, 0, newRow);
  } else if (action === "deleteRow") {
    if (newLines.length <= 3) {
      return modifyMarkdownTable(body, info, "deleteTable");
    }
    if (currentRowIndex === 0 || currentRowIndex === 1) {
      newLines.splice(2, 1);
    } else {
      newLines.splice(currentRowIndex, 1);
    }
  } else if (action === "addCol") {
    const targetCol = Math.min(colCount, currentColIndex + 1);
    for (let i = 0; i < newLines.length; i++) {
      const cells = parseRow(newLines[i]);
      if (i === 0) {
        cells.splice(targetCol, 0, `標題 ${colCount + 1}`);
      } else if (i === 1) {
        cells.splice(targetCol, 0, "---");
      } else {
        cells.splice(targetCol, 0, "  ");
      }
      newLines[i] = formatRow(cells);
    }
  } else if (action === "deleteCol") {
    if (colCount <= 1) {
      return modifyMarkdownTable(body, info, "deleteTable");
    }
    const targetCol = Math.min(colCount - 1, currentColIndex);
    for (let i = 0; i < newLines.length; i++) {
      const cells = parseRow(newLines[i]);
      cells.splice(targetCol, 1);
      newLines[i] = formatRow(cells);
    }
  }

  const nextTableStr = newLines.join("\n");
  const nextBody = body.slice(0, tableStartOffset) + nextTableStr + body.slice(tableEndOffset);
  const newCursor = Math.min(nextBody.length, tableStartOffset + nextTableStr.length);

  return {
    text: nextBody,
    selectionStart: newCursor,
    selectionEnd: newCursor,
    replaceFrom: tableStartOffset,
    replaceTo: tableEndOffset,
    insertText: nextTableStr,
  };
}

function TableGridPicker(props: {
  open: boolean;
  onClose(): void;
  onInsert(cols: number, rows: number): void;
  inTable: boolean;
  onAction(action: "addRow" | "deleteRow" | "addCol" | "deleteCol" | "deleteTable"): void;
