  const { open, onClose, onInsert, inTable, onAction } = props;
  const [hoverR, setHoverR] = useState(0);
  const [hoverC, setHoverC] = useState(0);

  if (!open) return null;

  const MAX_ROWS = 8;
  const MAX_COLS = 8;

  return (
    <div
      role="menu"
      data-table-picker
      style={{
        position: "absolute",
        top: "100%",
        left: 0,
        marginTop: 4,
        zIndex: 35,
        padding: 10,
        background: "var(--panel, #1e293b)",
        border: "1px solid var(--line, #475569)",
        borderRadius: 6,
        boxShadow: "0 6px 18px rgba(0, 0, 0, 0.32)",
