        <span>{hoverR > 0 && hoverC > 0 ? `${hoverC} × ${hoverR} 表格` : "選取表格欄列"}</span>
        <span className="muted" style={{ fontWeight: 400, fontSize: 11 }}>Word 式選取</span>
      </div>

      <div
        style={{
          display: "grid",
          gridTemplateColumns: `repeat(${MAX_COLS}, 16px)`,
          gap: 3,
          marginBottom: 8,
          cursor: "pointer",
        }}
        onMouseLeave={() => {
          setHoverR(0);
          setHoverC(0);
        }}
      >
        {Array.from({ length: MAX_ROWS * MAX_COLS }).map((_, idx) => {
          const r = Math.floor(idx / MAX_COLS) + 1;
          const c = (idx % MAX_COLS) + 1;
          const active = r <= hoverR && c <= hoverC;
          return (
            <div
              key={idx}
              onMouseEnter={() => {
                setHoverR(r);
                setHoverC(c);
              }}
              onClick={() => {
                onInsert(c, r);
                onClose();
              }}
              style={{
                width: 16,
                height: 16,
                border: "1px solid " + (active ? "var(--accent, #60a5fa)" : "var(--line, #475569)"),
                borderRadius: 2,
                background: active ? "rgba(96, 165, 250, 0.35)" : "rgba(255, 255, 255, 0.05)",
