// @depends-on ../api.ts (api, ApiError)
// @depends-on ../lib/media.ts (youtubeIdFromUrl：img 處理器遇到 ![](YouTube網址)、或 p 處理器遇到「整段只有一個 YouTube 網址」時，渲染為點擊播放的 YouTubeEmbed；這兩處是「外部網址不載入」規則僅有的例外)
// @depends-on ../lib/markdown.ts (HIGHLIGHT_COLOR_OPTIONS, cardIdFromHref, resolveLineInContext, type HighlightColor)
// @depends-on ../lib/liveMarkdown.ts (編輯中的即時渲染重寫了 ++／== 開合判定、顏色別名與圍欄判定；修改這裡的規則要同步改那邊)
// @depends-on ./Editor.tsx (fencedRanges／splitBodySegments：parseCollapsibleDoc 重寫了圍欄判定與巢狀深度配對，預覽與編輯的章節邊界必須一致；改其一要同步另一邊。只是規則同步標記，不可 import Editor)
import {
  Children,
  cloneElement,
  createContext,
  isValidElement,
  useContext,
  useEffect,
  useMemo,
  useState,
  type ReactElement,
  type ReactNode,
} from "react";
import ReactMarkdown from "react-markdown";
import { createPortal } from "react-dom";
import { api, ApiError } from "../api";
import {
  HIGHLIGHT_COLOR_OPTIONS,
  cardIdFromHref,
  resolveLineInContext,
  type HighlightColor,
} from "../lib/markdown";
import { mediaIdFromSrc, mediaUrl, urlTransform, youtubeIdFromUrl } from "../lib/media";
import { openLocalMedia, type OpenedMedia } from "../lib/mediaSource";
import { getPreferredDriverType } from "../lib/storage";
import type { MediaInfo } from "../types";

const infoCache = new Map<string, Promise<MediaInfo>>();
const mediaWidthCache = new Map<string, string>();
function getInfo(id: string): Promise<MediaInfo> {
  let p = infoCache.get(id);
  if (!p) {
    p = api.mediaInfo(id);
    infoCache.set(id, p);
    p.catch(() => infoCache.delete(id)); // 失敗不快取，之後補上檔案就能恢復
  }
  return p;
}

type State =
  | { status: "loading" }
  | { status: "ok"; info: MediaInfo; src: string }
  | { status: "missing" }
  | { status: "unavailable"; reason: string };

// 電腦版沿用後端網址（行為不變）；iPad／網頁版讀本機 IndexedDB，沒有才從 Drive 下載。null＝確定遺失
async function openMedia(id: string): Promise<OpenedMedia | null> {
  if (getPreferredDriverType() === "dexie") return openLocalMedia(id);
  return getInfo(id).then(
    (info) => ({ info, src: mediaUrl(id), revoke: () => {} }),
    () => null,
  );
}

export function MediaEmbed({
  id,
  explicitWidth,
  onChangeWidth,
  onRemove,
}: {
  id: string;
  explicitWidth?: string;
  onChangeWidth?: (width: string) => void;
  onRemove?: () => void;
}) {
  const [state, setState] = useState<State>({ status: "loading" });
  const [userWidth, setUserWidth] = useState<string | null>(
    () => explicitWidth || mediaWidthCache.get(id) || null,
  );
  const [zoomed, setZoomed] = useState(false);
  const [attempt, setAttempt] = useState(0);

  useEffect(() => {
    if (!zoomed) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") setZoomed(false);
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [zoomed]);

  useEffect(() => {
    if (explicitWidth) {
      mediaWidthCache.set(id, explicitWidth);
      setUserWidth(explicitWidth);
    }
  }, [explicitWidth, id]);

  const changeWidth = (w: string) => {
    mediaWidthCache.set(id, w);
    setUserWidth(w);
    onChangeWidth?.(w);
  };

  useEffect(() => {
    let alive = true;
    let revoke: (() => void) | null = null;
    setState({ status: "loading" });
    openMedia(id).then(
      (m) => {
        if (!alive) {
          m?.revoke();
          return;
        }
        if (!m) {
          setState({ status: "missing" });
          return;
        }
        revoke = m.revoke;
        setState({ status: "ok", info: m.info, src: m.src });
      },
      (e) => {
        console.error(`圖片 ${id} 載入失敗`, e);
        if (alive) setState({ status: "unavailable", reason: e instanceof Error ? e.message : String(e) });
      },
    );
    return () => {
      alive = false;
      revoke?.();
    };
  }, [id, attempt]);

  if (state.status === "loading") return <span className="media-loading">載入中…</span>;
  if (state.status === "unavailable")
    return (
      <span
        className="media-missing"
        role="button"
        tabIndex={0}
        aria-label="圖片尚未下載，點擊重試"
        style={{ cursor: "pointer" }}
        onClick={(e) => {
          e.stopPropagation();
          setAttempt((n) => n + 1);
        }}
      >
        圖片尚未下載（點擊重試）：{state.reason.slice(0, 80)}
      </span>
    );
  if (state.status === "missing")
    return (
      <span className="media-missing" role="img" aria-label="圖片遺失">
        圖片遺失：{id.slice(0, 8)}
      </span>
    );
  const onError = () => {
    infoCache.delete(id);
    setState({ status: "missing" });
  };
  if (state.info.kind === "video")
    return (
      <video
        className="nodrag nowheel"
        style={{ width: userWidth ?? "100%", maxWidth: "100%", borderRadius: 4 }}
        src={state.src}
        controls
        preload="metadata"
        onError={onError}
      />
    );

  return (
    <span
      className="media-embed-wrap"
      style={
        userWidth
          ? { display: "block", width: userWidth, maxWidth: "100%" }
          : { display: "inline-block", maxWidth: "100%" }
      }
    >
      <img
        ref={(el) => {
          if (!el) return;
          el.style.setProperty("width", "100%", "important");
          el.style.setProperty("max-width", "100%", "important");
          el.style.setProperty("max-height", "none", "important");
          el.style.setProperty("height", "auto", "important");
          el.style.setProperty("object-fit", "unset", "important");
          el.style.setProperty("margin", "0", "important");
        }}
        src={state.src}
        alt=""
        loading="lazy"
        onError={onError}
        style={{
          width: "100%",
          maxWidth: "100%",
          maxHeight: "none",
          height: "auto",
          objectFit: "unset",
          margin: 0,
          borderRadius: 4,
          display: "block",
        }}
      />
      <span
        className="media-size-bar nodrag nowheel"
        style={{ display: "inline-flex", gap: 4, marginTop: 3 }}
        onClick={(e) => e.stopPropagation()}
        onDoubleClick={(e) => e.stopPropagation()}
      >
        <button
          type="button"
          style={{
            fontSize: 10,
            padding: "1px 5px",
            opacity: userWidth === "33%" ? 1 : 0.7,
            fontWeight: userWidth === "33%" ? 600 : 400,
            cursor: "pointer",
          }}
          onClick={() => changeWidth("33%")}
        >
          小
        </button>
        <button
          type="button"
          style={{
            fontSize: 10,
            padding: "1px 5px",
            opacity: userWidth === "60%" ? 1 : 0.7,
            fontWeight: userWidth === "60%" ? 600 : 400,
            cursor: "pointer",
          }}
          onClick={() => changeWidth("60%")}
        >
          中
        </button>
        <button
          type="button"
          style={{
            fontSize: 10,
            padding: "1px 5px",
            opacity: userWidth === "100%" ? 1 : 0.7,
            fontWeight: userWidth === "100%" ? 600 : 400,
            cursor: "pointer",
          }}
          onClick={() => changeWidth("100%")}
        >
          滿版
        </button>
        <button
          type="button"
          style={{ fontSize: 10, padding: "1px 5px", opacity: 0.7, cursor: "pointer" }}
          onClick={() => setZoomed(true)}
        >
          🔍 放大
        </button>
        {onRemove && (
          <button
            type="button"
            style={{ fontSize: 10, padding: "1px 5px", opacity: 0.85, color: "#f87171", cursor: "pointer" }}
            onClick={onRemove}
            title="從卡片內文移除此圖片"
          >
            🗑️ 移除
          </button>
        )}
      </span>
      {zoomed &&
        createPortal(
          <div
            className="nodrag nowheel"
            onClick={(e) => {
              e.stopPropagation();
              setZoomed(false);
            }}
            onDoubleClick={(e) => e.stopPropagation()}
            style={{
              position: "fixed",
              inset: 0,
              zIndex: 10000,
              background: "rgba(0, 0, 0, 0.88)",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              cursor: "zoom-out",
            }}
          >
            <img
              src={state.src}
              alt=""
              style={{ width: "96vw", height: "96vh", objectFit: "contain" }}
            />
          </div>,
          document.body,
        )}
    </span>
  );
}

// ---- YouTube 嵌入：預設只顯示縮圖，點擊後才建立 iframe（不點就不連 youtube-nocookie.com）----
function YouTubeEmbed({ id, title }: { id: string; title: string }) {
  const [playing, setPlaying] = useState(false);
  const [thumbFailed, setThumbFailed] = useState(false);
  return (
    <span
      className="yt-embed nodrag nowheel"
      style={{ display: "block", width: "100%", maxWidth: 560, margin: "6px 0" }}
      onClick={(e) => e.stopPropagation()}
      onDoubleClick={(e) => e.stopPropagation()}
    >
      <span
        style={{
          display: "block",
          position: "relative",
          width: "100%",
          aspectRatio: "16 / 9",
          background: "#000",
          borderRadius: 6,
          overflow: "hidden",
        }}
      >
        {playing ? (
          <iframe
            src={`https://www.youtube-nocookie.com/embed/${id}?autoplay=1&rel=0`}
            title={title || "YouTube 影片"}
            allow="autoplay; encrypted-media; picture-in-picture; fullscreen"
            allowFullScreen
            referrerPolicy="strict-origin-when-cross-origin"
            style={{ position: "absolute", inset: 0, width: "100%", height: "100%", border: 0 }}
          />
        ) : (
          <button
            type="button"
            aria-label={title ? `播放影片：${title}` : "播放 YouTube 影片"}
            onClick={() => setPlaying(true)}
            style={{
              position: "absolute",
              inset: 0,
              width: "100%",
              height: "100%",
              padding: 0,
              border: 0,
              background: "transparent",
              cursor: "pointer",
            }}
          >
            {!thumbFailed && (
              <img
                ref={(el) => {
                  if (!el) return;
                  el.style.setProperty("width", "100%", "important");
                  el.style.setProperty("height", "100%", "important");
                  el.style.setProperty("max-width", "none", "important");
                  el.style.setProperty("max-height", "none", "important");
                  el.style.setProperty("object-fit", "cover", "important");
                  el.style.setProperty("margin", "0", "important");
                }}
                src={`https://i.ytimg.com/vi/${id}/hqdefault.jpg`}
                alt=""
                loading="lazy"
                onError={() => setThumbFailed(true)}
                style={{ position: "absolute", inset: 0, display: "block" }}
              />
            )}
            <span
              style={{
                position: "absolute",
                left: "50%",
                top: "50%",
                transform: "translate(-50%, -50%)",
                width: 56,
                height: 40,
                borderRadius: 10,
                background: "rgba(220, 38, 38, 0.92)",
                color: "#fff",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                fontSize: 20,
              }}
            >
              ▶
            </span>
          </button>
        )}
      </span>
      <a
        href={`https://www.youtube.com/watch?v=${id}`}
        target="_blank"
        rel="noreferrer noopener"
        style={{ fontSize: 11 }}
      >
        在 YouTube 開啟{title ? `：${title}` : ""}
      </a>
    </span>
  );
}

// ---- 卡片引用（@ 引用）狀態快取、開啟卡片通道與改名／刪除即時通知 ---- ----
export type CardRefResolution =
  | { status: "ok"; title: string }
  | { status: "deleted" }
  | { status: "fallback" };

const cardRefCache = new Map<string, Promise<CardRefResolution>>();
const cardRefListeners = new Map<string, Set<(res: CardRefResolution) => void>>();

function isNotFoundError(e: unknown): boolean {
  if (e instanceof ApiError) {
    return e.status === 404 || e.code === "NOT_FOUND";
  }
  if (e && typeof e === "object") {
    const rec = e as { code?: unknown; status?: unknown };
    return rec.code === "NOT_FOUND" || rec.status === 404;
  }
  return false;
}

function resolveCardTitle(id: string): Promise<CardRefResolution> {
  let p = cardRefCache.get(id);
  if (!p) {
    p = api.cardTitle(id).then(
      (r): CardRefResolution => ({ status: "ok", title: r.title }),
      (e): CardRefResolution => {
        if (isNotFoundError(e)) {
          return { status: "deleted" };
        }
        // 暫時連不上伺服器或非 404 錯誤：不快取失敗，退回顯示原本的文字，絕不誤判成已刪除
        cardRefCache.delete(id);
        return { status: "fallback" };
      },
    );
    cardRefCache.set(id, p);
  }
  return p;
}

export function notifyCardTitleUpdated(id: string, title: string): void {
  const res: CardRefResolution = { status: "ok", title };
  cardRefCache.set(id, Promise.resolve(res));
  cardRefListeners.get(id)?.forEach((fn) => fn(res));
}

export function notifyCardDeleted(id: string): void {
  const res: CardRefResolution = { status: "deleted" };
  cardRefCache.set(id, Promise.resolve(res));
  cardRefListeners.get(id)?.forEach((fn) => fn(res));
}

export function clearCardRefCache(): void {
  cardRefCache.clear();
}

// 訂閱某張卡片的標題狀態：先查一次，之後改名／刪除會即時推送；回傳取消訂閱函式
export function subscribeCardTitle(id: string, cb: (res: CardRefResolution) => void): () => void {
  let alive = true;
  resolveCardTitle(id).then((r) => {
    if (alive) cb(r);
  });
  let set = cardRefListeners.get(id);
  if (!set) {
    set = new Set();
    cardRefListeners.set(id, set);
  }
  const listener = (next: CardRefResolution) => {
    if (alive) cb(next);
  };
  set.add(listener);
  return () => {
    alive = false;
    set?.delete(listener);
  };
}

const CardOpenContext = createContext<((cardId: string) => void) | undefined>(undefined);

export function CardOpenProvider({
  onOpenCard,
  children,
}: {
  onOpenCard?: (cardId: string) => void;
  children: ReactNode;
}) {
  return <CardOpenContext.Provider value={onOpenCard}>{children}</CardOpenContext.Provider>;
}

export function CardRef({
  id,
  children,
  onOpenCard,
}: {
  id: string;
  children: ReactNode;
  onOpenCard?: (cardId: string) => void;
}) {
  const ctxOpen = useContext(CardOpenContext);
  const open = onOpenCard ?? ctxOpen;
  const [res, setRes] = useState<CardRefResolution | null>(null);

  useEffect(() => subscribeCardTitle(id, setRes), [id]);

  if (res?.status === "deleted") {
    return (
      <span className="card-ref deleted" data-testid={`card-ref-deleted-${id}`}>
        （已刪除的卡片）
      </span>
    );
  }

  const display =
    res?.status === "ok" ? res.title || "（無標題）" : children;

  return (
    <a
      href={`#card:${id}`}
      className="card-ref nodrag"
      onClick={(e) => {
        e.preventDefault();
        e.stopPropagation();
        open?.(id);
      }}
    >
      {display}
    </a>
  );
}

function markdownUrlTransform(url: string, key?: string, node?: unknown): string {
  if (typeof url === "string" && url.startsWith("card:")) {
    return url;
  }
  return (urlTransform as (u: string, k?: string, n?: unknown) => string)(url, key, node);
}

function parseAltWidth(alt: unknown): string | undefined {
  if (typeof alt !== "string") return undefined;
  const pipeIdx = alt.lastIndexOf("|");
  if (pipeIdx < 0) return undefined;
  const raw = alt.slice(pipeIdx + 1).trim();
  if (!raw) return undefined;
  const num = Number(raw);
  if (Number.isFinite(num) && num > 0) {
    return String(Math.round(num)) + "px";
  }
  if (raw.endsWith("px") || raw.endsWith("%")) {
    const unitLen = raw.endsWith("px") ? -2 : -1;
    const prefix = raw.slice(0, unitLen).trim();
    const unitNum = Number(prefix);
    if (Number.isFinite(unitNum) && unitNum > 0) {
      return raw;
    }
  }
  return undefined;
}

function isMarkdownTable(text: string): boolean {
  const lines = text.trim().split("\n").map((l) => l.trim());
  if (lines.length < 2) return false;
  const isRow = (l: string) => l.startsWith("|") && l.endsWith("|") && l.length >= 2;
  const isSep = (l: string) => /^\s*\|(\s*:?-+:?\s*\|)+\s*$/.test(l);
  return isRow(lines[0]) && isSep(lines[1]) && lines.slice(2).every(isRow);
}

function MarkdownTableRenderer({ rawText, onOpenCard }: { rawText: string; onOpenCard?: (cardId: string) => void }) {
  const lines = rawText.trim().split("\n").map((l) => l.trim());
  const parseCells = (line: string) =>
    line
      .slice(1, -1)
      .split("|")
