  const headerCells = parseCells(lines[0]);
  const dataRows = lines.slice(2).map(parseCells);

  const renderCellMarkdown = (cell: string) => (
    <ReactMarkdown
      urlTransform={markdownUrlTransform}
      components={{
        p: ({ children }) => <>{renderRichChildren(children)}</>,
        a: ({ href, children }) => {
          const cardId = cardIdFromHref(typeof href === "string" ? href : undefined);
          if (cardId) return <CardRef id={cardId} onOpenCard={onOpenCard}>{children}</CardRef>;
          return <a href={href} target="_blank" rel="noreferrer noopener">{children}</a>;
        },
      }}
    >
      {cell}
    </ReactMarkdown>
  );

  return (
    <div className="md-table-wrap nodrag" style={{ overflowX: "auto", margin: "10px 0" }}>
      <table
        style={{
          width: "100%",
          borderCollapse: "collapse",
          fontSize: 13,
          textAlign: "left",
          border: "1px solid var(--line, #334155)",
          borderRadius: 6,
          overflow: "hidden",
        }}
      >
        <thead>
          <tr style={{ background: "var(--panel-sub, rgba(255, 255, 255, 0.05))", borderBottom: "2px solid var(--line, #475569)" }}>
            {headerCells.map((h, i) => (
              <th key={i} style={{ padding: "6px 10px", fontWeight: 600, borderRight: "1px solid var(--line, #334155)" }}>
                {renderCellMarkdown(h)}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {dataRows.map((row, rIdx) => (
            <tr
              key={rIdx}
              style={{
                borderBottom: "1px solid var(--line, #334155)",
                background: rIdx % 2 === 1 ? "var(--table-alt, rgba(255, 255, 255, 0.02))" : "transparent",
              }}
            >
              {row.map((cell, cIdx) => (
                <td key={cIdx} style={{ padding: "6px 10px", borderRight: "1px solid var(--line, #334155)" }}>
                  {renderCellMarkdown(cell)}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

interface CollapsibleDocPart {
  kind: "markdown" | "details";
  text?: string;
  summary?: string;
  content?: string;
  open?: boolean;
}

// 圍欄代碼塊的範圍（含開頭與結尾行）：判定與 Editor.tsx fencedRanges 相同。
// 原因：收摺標籤出現在代碼裡只是代碼文字，惰性 regex 不看圍欄就會把它切成章節。
function fencedRanges(body: string): [number, number][] {
  const ranges: [number, number][] = [];
  let open = -1;
  let openLen = 0;
  let pos = 0;
  while (pos <= body.length) {
    let nl = body.indexOf("\n", pos);
    if (nl < 0) nl = body.length;
    const t = body.slice(pos, nl).trim();
    if (open < 0) {
      if (t.startsWith("`".repeat(3))) {
        openLen = 0;
        while (t[openLen] === "`") openLen++;
        open = pos;
      }
    } else if (t.length >= openLen && t.replace(/`/g, "") === "") {
      ranges.push([open, nl]);
      open = -1;
    }
    pos = nl + 1;
  }
  if (open >= 0) ranges.push([open, body.length]);
  return ranges;
}

// 與 Editor.tsx splitBodySegments 相同：先找開標籤＋summary，再以巢狀深度找對應的 </details>，
// 圍欄內的標籤一律略過；這樣預覽的章節邊界才會和編輯模式一致。
function parseCollapsibleDoc(source: string): CollapsibleDocPart[] {
  const parts: CollapsibleDocPart[] = [];
  const openRe = /<details(\s+open)?>\s*<summary>([\s\S]*?)<\/summary>/gi;
  const tagRe = /<details(?:\s+open)?>|<\/details>/gi;
  const fences = fencedRanges(source);
  const inFence = (i: number) => fences.some(([a, b]) => i >= a && i < b);
  let lastIndex = 0;
  let m: RegExpExecArray | null;
  while ((m = openRe.exec(source)) !== null) {
    if (inFence(m.index)) continue;
    const summaryEnd = m.index + m[0].length;
    let depth = 1;
    let closeStart = -1;
    let t: RegExpExecArray | null;
    tagRe.lastIndex = summaryEnd;
    while ((t = tagRe.exec(source)) !== null) {
      if (inFence(t.index)) continue;
      depth += t[0].startsWith("</") ? -1 : 1;
      if (depth === 0) {
        closeStart = t.index;
        break;
      }
    }
    // 沒有對應的 </details>：保持一般文字，不切段
    if (closeStart < 0) continue;
    const closeEnd = closeStart + "</details>".length;
    if (m.index > lastIndex) {
      parts.push({ kind: "markdown", text: source.slice(lastIndex, m.index) });
    }
    parts.push({
      kind: "details",
      open: Boolean(m[1]),
      summary: m[2].trim(),
      content: source.slice(summaryEnd, closeStart).replace(/^\n+|\n+$/g, ""),
    });
    lastIndex = closeEnd;
    openRe.lastIndex = closeEnd;
  }
  if (lastIndex < source.length) {
    parts.push({ kind: "markdown", text: source.slice(lastIndex) });
  }
  return parts;
}

function CollapsibleDetailsSection({
