td,th{padding:6px 8px;border:1px solid var(--line);text-align:left}
th{background:var(--panel)}
.hi{color:var(--danger);font-weight:700}
.empty,.hint,small{color:var(--muted)}
.empty{padding:16px 4px}
#lb{position:fixed;inset:0;z-index:9;background:rgba(0,0,0,.88);display:flex;align-items:center;justify-content:center;overflow:auto;padding:calc(16px + env(safe-area-inset-top,0px)) 16px calc(16px + env(safe-area-inset-bottom,0px));cursor:zoom-out}
#lb img{max-width:100%;max-height:100%;background:#fff}
.ck{display:inline-flex;align-items:center;gap:4px;margin:0;font-weight:400}
.ck input{width:auto;margin:0}
button.chip{background:var(--accent-soft);border:0;border-radius:12px;padding:1px 10px;font-size:12px}
.ed small,.tg small{display:block;margin-top:6px}
.tg{margin-top:8px}
progress{width:100%;height:8px;accent-color:var(--danger)}
.br{display:grid;grid-template-columns:minmax(6em,30%) 1fr auto auto;gap:8px;align-items:center;margin:6px 0}
.br span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}

/* 彙整：科目＞章節＞概念三層（上一輪加的） */
details.sj{margin:14px 0;padding-top:6px;border-top:1px solid var(--line)}
details.sj>summary{font-size:15px;font-weight:700;color:var(--text)}
details.ch{margin:6px 0 6px 12px;padding-left:12px;border-left:2px solid var(--accent)}
details.ch>summary{color:var(--text)}
.cn{margin:2px 0 2px 8px;font-size:13px;color:var(--muted)}
.cn.hi{color:var(--danger)}
/* 依類別抽題的樹（上一輪加的） */
.cat-s{margin:6px 0;padding:6px 0;border-top:1px solid var(--line)}
.cat-c{display:flex;flex-wrap:wrap;gap:4px 14px;margin:4px 0 0 22px}

/* 觸控裝置：與卡片軟體一樣加大點擊熱區 */
@media (pointer:coarse){button:not(.ghost):not(.chip),.btn{min-height:38px}.stem{font-size:16px}}

/* 整合功能面板 */
.dash-board{display:flex;flex-direction:column;gap:10px;margin:0 0 16px}
.dash-sec{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:12px 14px}
.dash-sec h3{margin:0 0 8px;font-size:12px;font-weight:700;color:var(--muted);letter-spacing:.02em}
.dash-row{display:flex;flex-wrap:wrap;gap:6px 10px;align-items:center}

/* 浮動題號快速定位選單 */
.qnav{position:fixed;right:16px;bottom:calc(16px + env(safe-area-inset-bottom,0px));z-index:8}
.qnav summary{list-style:none;background:var(--accent);color:#fff;font-weight:600;font-size:13px;padding:7px 14px;border-radius:20px;box-shadow:0 3px 12px rgba(0,0,0,.25);cursor:pointer;user-select:none;display:inline-flex;align-items:center;gap:4px}
.qnav summary::-webkit-details-marker{display:none}
.qnav[open] summary{background:var(--panel);color:var(--text);border:1px solid var(--line)}
.qnav-menu{position:absolute;bottom:calc(100% + 8px);right:0;max-height:50vh;width:260px;background:var(--card);border:1px solid var(--line);border-radius:12px;box-shadow:0 8px 24px rgba(0,0,0,.3);overflow-y:auto;padding:8px;display:grid;grid-template-columns:repeat(5,1fr);gap:4px}
.qnav-menu button{padding:6px 0;font-size:12px;font-weight:600;border-radius:6px;border:1px solid var(--line);background:var(--panel);color:var(--text);cursor:pointer}
.qnav-menu button.done{background:var(--accent-soft);border-color:var(--accent);color:var(--accent)}
.qnav-menu button.ok{background:color-mix(in srgb,var(--ok) 22%,var(--panel));border-color:var(--ok);color:var(--ok)}
.qnav-menu button.ng{background:color-mix(in srgb,var(--danger) 20%,var(--panel));border-color:var(--danger);color:var(--danger)}
</style>
</head>
<body>
<div id="app"></div>
<script>
/*PARSE_START*/
const uid=()=>Math.random().toString(36).slice(2,9);
// 原因：原寫法直接刪掉 <sub>/<sup>，41₁₆ 變成「4116」；數字轉成 Unicode 上下標，其他內容以 _()、^() 保留，才不會悄悄改變題意。
const SUBD='₀₁₂₃₄₅₆₇₈₉',SUPD='⁰¹²³⁴⁵⁶⁷⁸⁹';
const nrm=s=>String(s).normalize('NFC').replace(/[\u2E80-\u2FDF]/g,c=>c.normalize('NFKC'))
  .replace(/<sub>([^<]*)<\/sub>/gi,(m,t)=>/^\d+$/.test(t)?[...t].map(d=>SUBD[d]).join(''):'_('+t+')')
  .replace(/<sup>([^<]*)<\/sup>/gi,(m,t)=>/^\d+$/.test(t)?[...t].map(d=>SUPD[d]).join(''):'^('+t+')')
  .replace(/<\/?(?:sub|sup)>/gi,'');
const jn=(a,b)=>/[A-Za-z0-9]$/.test(a)&&/^[A-Za-z0-9]/.test(b)?a+' '+b:a+b;
const base=s=>String(s||'').split('/').pop();
// 原因：MinerU 把公式放在 type 為 inline_equation / interline_equation 的 span，content 不帶 $；不包起來，渲染層就認不出邊界。
const mathSpan=s=>{
  const c=s.content||'';
  if(!/equation/i.test(s.type||''))return c;
  const t=c.trim().replace(/\s*\n\s*/g,' ');
  if(!t||t[0]==='$')return c;
  return /interline/i.test(s.type)?'$$'+t+'$$':'$'+t+'$';
};
// 原因：MinerU 會把一串算式切成好幾個連續的 inline_equation span（2x^{2}+7x+3\leq0 與 \Rightarrow… 各一段）；各自包 $ 會變成 $a$$b$，$$ 又會被當成顯示模式的分隔符。連續的算式 span 先合併成一個。
const lineText=sp=>{
  const o=[];let eq=null;
  const fl=()=>{if(eq!==null){const t=eq.trim().replace(/\s*\n\s*/g,' ');if(t)o.push('$'+t+'$');eq=null}};
  sp.forEach(s=>{
    const c=s.content||'';
    if(/inline_equation/i.test(s.type||'')&&c.trim()&&c.trim()[0]!=='$')eq=eq===null?c:eq+' '+c;
    else{fl();o.push(mathSpan(s))}
  });
  fl();return o.join('');
};
// 原因：MinerU 常把整段算式（x^{2}-8x+5(\alpha-\beta)=0、\overrightarrow{OS}）當純文字輸出，不帶 $；只包反斜線指令會留下沒包的 x^{2}。
// 做法：掃出「可能是算式」的連續片段（英數、運算符號、LaTeX 指令；遇到中文、全形標點或換行就斷開；\text{…}、\begin…\end 整組視為一體），片段內有 LaTeX 特徵才整段包成 $…$。已經有 $ 的片段不動，所以重複執行結果不變。
const MCH=/[A-Za-z0-9 \t\\^_{}()\[\]=+\-*\/<>|.,:;'!?]/;
const groupEnd=(s,i)=>{let d=0;for(let j=i;j<s.length;j++){if(s[j]==='\\'){j++;continue}if(s[j]==='{')d++;else if(s[j]==='}'&&--d===0)return j+1}return -1};
const envEnd=(s,i,name)=>{const o='\\begin{'+name+'}',c='\\end{'+name+'}';let d=0,j=i;while(j<s.length){if(s.startsWith(o,j)){d++;j+=o.length}else if(s.startsWith(c,j)){j+=c.length;if(--d===0)return j}else j++}return s.length};
const wrapRun=r=>{
  if(!/\\[A-Za-z]|[\^_]\{|[A-Za-z0-9)\]}]\^[0-9A-Za-z]|[A-Za-z]_[0-9A-Za-z]/.test(r))return r;
  const m=/^([ \t]*(?:[(（](?:[A-Ha-h]|\d{1,2})[)）][ \t]*)?)([\s\S]*?)([ \t.,;:]*)$/.exec(r);
  return m[2]?m[1]+'$'+m[2]+'$'+m[3]:r;
};
const wrapRuns=s=>{
  let out='',run='';
  const end=()=>{out+=wrapRun(run);run=''};
  for(let i=0;i<s.length;){
    const c=s[i];
    if(c==='\\'){
      let m=/^\\begin\{([A-Za-z*]+)\}/.exec(s.slice(i,i+40));
      if(m){const e=envEnd(s,i,m[1]);run+=s.slice(i,e);i=e;continue}
      m=/^\\[A-Za-z]+/.exec(s.slice(i,i+40));
      if(m){run+=m[0];i+=m[0].length;while(s[i]==='{'){const e=groupEnd(s,i);if(e<0)break;run+=s.slice(i,e);i=e}continue}
      run+=s.slice(i,i+2);i+=2;continue;
    }
    if(MCH.test(c)){run+=c;i++;continue}
    end();out+=c;i++;
  }
  end();return out;
};
const wrapBareLatex=str=>{
  if(!str||!/[\\^_]/.test(str))return str;
  return str.split(/(\$\$[\s\S]*?\$\$|\$[^$\n]+?\$)/).map((part,i)=>i%2?part:wrapRuns(part)).join('');
};
// 原因：公式的圖檔（image_path）與 LaTeX 文字是同一個東西；記下這些圖檔的 ID，補圖面板就不會把它們當成漏掉的圖。
const eqImgIds=(j,pre)=>{const r=[];const w=b=>{(b.lines||[]).forEach(l=>(l.spans||[]).forEach(s=>{if(/equation/i.test(s.type||'')&&s.image_path)r.push(pre+'__'+base(s.image_path))}));(b.blocks||[]).forEach(w)};(j.pdf_info||[]).forEach(pg=>(pg.para_blocks||[]).forEach(w));return r};
const linesOf=b=>b.lines?b.lines.map(l=>nrm(lineText(l.spans||[]))):(b.blocks||[]).flatMap(linesOf);
const spansOf=b=>[...(b.lines||[]).flatMap(l=>l.spans||[]),...(b.blocks||[]).flatMap(spansOf)];
const po=(p,q)=>(p.passages||[]).find(x=>x.id===q.pid);

function fromMineru(j, scopePrefix){
  const out=[];
  j.pdf_info.forEach((pg,pi)=>{if(pi>0)out.push({t:'brk'});pg.para_blocks.forEach(b=>{
    // 原因：頁首過濾（y≤62）會誤殺貼在頁面最上緣、只有一行的「14. …」詳解或題目；開頭是題號的區塊一律保留。
    if(pi>0&&b.bbox&&b.bbox[3]<=62&&(b.type==='title'||b.type==='text')&&!/^\s*\d{1,3}\s*[.．、](?!\d)/.test(linesOf(b)[0]||''))return;
    // 原因：圖表（chart）區塊原本沒人處理，折線圖等圖檔在資料夾裡卻不屬於任何題目。
    if(b.type==='image'||b.type==='table'||b.type==='chart'){
      (b.blocks||[]).forEach(s=>{
        if(/caption|footnote/.test(s.type)){const ls=linesOf(s);if(ls.length)out.push({t:'text',ls})}
        else spansOf(s).forEach(sp=>{
          if(sp.image_path||sp.html){
            const rawId=base(sp.image_path);
            const scopedId=rawId ? (scopePrefix ? scopePrefix+'__'+rawId : rawId) : '';
            out.push({t:b.type==='table'?'tbl':'img',id:scopedId,html:sp.html||''});
          }
        });
      });
    }else if(b.type==='code')out.push({t:'code',v:linesOf(b).join('\n')});
    else out.push({t:'text',ls:linesOf(b)});
  })});
  return out;
}

function fromText(t, scopePrefix){
  const out=[];
  for(let l of nrm(t).split(/\r?\n/)){
    l=l.trim().replace(/^#+\s*/,'');if(!l)continue;
    let m;
    if(/^<table/i.test(l))out.push({t:'tbl',id:'',html:l});
    else if((m=l.match(/^!\[[^\]]*\]\(([^)]*)\)/))){
      const rawId=base(m[1]);
      const scopedId=rawId ? (scopePrefix ? scopePrefix+'__'+rawId : rawId) : '';
      out.push({t:'img',id:scopedId,html:''});
    }
    else out.push({t:'text',ls:[l]});
  }
  return out;
}

const IMPORTERS=[
  {id:'mineru',label:'MinerU layout.json',detect:b=>!!(b.json&&b.json.pdf_info),blocks:(b,pre)=>fromMineru(b.json,pre)},
  {id:'text',label:'文字／Markdown',detect:b=>!!b.text,blocks:(b,pre)=>fromText(b.text,pre)}
];

function keyFromHtml(h,k){
  for(const r of h.match(/<tr[^>]*>.*?<\/tr>/gis)||[]){
    const c=[...r.matchAll(/<t[dh][^>]*>(.*?)<\/t[dh]>/gis)].map(m=>m[1].replace(/<[^>]*>/g,'').trim());
    for(let i=0;i+1<c.length;i+=2)if(/^\d{1,3}$/.test(c[i])&&/^[A-Ha-h]{1,8}$/.test(c[i+1]))k[+c[i]]=c[i+1].toUpperCase();
    // 原因：國文詳解的答案表是「1.(C)」同一格，題號與字母沒分開，上面那行讀不到；這行逐格讀這種寫法。
    c.forEach(x=>{const m=x.match(/^(\d{1,3})\s*[.、．]?\s*[(（]([A-Ha-h]{1,8})[)）]$/);if(m)k[+m[1]]=m[2].toUpperCase()});
  }
}
function parseKey(t){
  const k={};
  if(/^\s*\{/.test(t)){try{const o=JSON.parse(t);for(const n in o)k[+n]=String(o[n]).toUpperCase();return k}catch(e){}}
  const re=/(\d{1,3})\s*[.、．:：)）\-—]?\s*([A-Ha-h]{1,8})(?![A-Za-z])/g;let m;
  while((m=re.exec(t)))k[+m[1]]=m[2].toUpperCase();
  if(!Object.keys(k).length)[...t.replace(/[^A-Za-z]/g,'').toUpperCase()].forEach((c,i)=>k[i+1]=c);
  return k;
}
function splitOpts(s){
  for(const mk of [k=>new RegExp('[(（]'+k+'[)）]'),k=>new RegExp('(?:^|\\n)\\s*'+k+'\\s*[.、．]'),k=>new RegExp('(?:^|\\s)'+k+'\\s*[.、．]')]){
    const pos=[];let from=0;
    for(const k of 'ABCDEFGH'){
      const m=mk(k).exec(s.slice(from));if(!m)break;
      pos.push([k,from+m.index,from+m.index+m[0].length]);from+=m.index+m[0].length;
    }
    if(pos.length>=2)return{stem:s.slice(0,pos[0][1]).trim(),opts:pos.map((p,i)=>({k:p[0],v:s.slice(p[2],pos[i+1]?pos[i+1][1]:undefined).trim()}))};
  }
  return{stem:s.trim(),opts:[]};
}
function assemble(blocks,keyText){
  const qs=[],ps=[],kh=[],kl=[],exs=[];let cur=null,pc=null,last=0,inKey=false,inNotice=false,ex=null,exLast=0,pre=null;
  // 原因：非選擇題、詳解區的非選擇題答案、題組前導內容各需要獨立的暫存，不能再混進 cur／ex。
  const nms=[],nrf=[],L={blocks:[]};let inNM=false,inWR=false,inKN=false,nsec=null,nc=null,nrc=null;
  const noise=/公告試題僅供參考|^【?以下空白】?$|第\s*\d+\s*頁\s*共\s*\d+\s*頁|准考證號碼|座位及准考證/;
  const push=(t,s,cont)=>{const a=t.blocks,l=a[a.length-1];if(l&&l.t==='text')l.v=cont?jn(l.v,s):l.v+'\n'+s;else a.push({t:'text',v:s})};
  const flushLead=()=>{if(L.blocks.length){if(ex)ex.blocks.push(...L.blocks);L.blocks=[]}};
  for(let b of blocks){
    // 原因：MinerU 會把 21~28 題的詳解判成 code 區塊，整塊併在前一題；在詳解區把它改成逐行處理的文字，才切得出各題編號。
    if(b.t==='code'&&inKey)b={t:'text',ls:b.v.split('\n'),cz:1};
    // 原因：換頁標記只在「詳解編號缺漏」時用來判斷從哪裡切開，不屬於任何題目內容。
    if(b.t==='brk'){if(inKey&&ex&&ex.blocks.length){ex.cuts.push(ex.blocks.length);ex.fresh=true}continue}
    if(b.t!=='text'){
      if(inKey){
        // 原因：詳解區的表格可能是答案表（要讀答案），也可能是詳解裡的算式表（要留給該題詳解）；讀得出答案才當答案表。
        const kt={};if(b.html)keyFromHtml(b.html,kt);
        if(Object.keys(kt).length)kh.push(b.html);else if(inKN){if(nrc)nrc.blocks.push(b)}else if(ex&&ex.closed&&ex.no>0)L.blocks.push(b);else if(ex){ex.blocks.push(b);ex.fresh=false}
      }else if(inNM){if(nc)nc.blocks.push(b)}else{const g=cur||pc;if(g)g.blocks.push(b)}
      continue;
    }
    let first=true;
    for(let s of b.ls){
      // 原因：「注意事項」結束句（…請先填寫准考證號碼及姓名，再翻閱試題本作答）本身含 noise 關鍵字，被先攔掉就永遠偵測不到結束，inNotice 卡住、後面整份題目全被略過。注意事項內的行改由下面的 inNotice 區段處理。
      s=s.trim();if(!s||(!inNotice&&noise.test(s)))continue;
      const f=first;first=false;let m;
      // 原因：OCR 可能把標題輸出成簡體「项」，只認「項」會讓注意事項不被跳過，其內容被當成第 1~8 題。
      if(/【\s*注\s*意\s*事\s*[項项]\s*】/.test(s)){inNotice=true;continue}
      if(inNotice){if(/翻閱試題本作答|開始作答/.test(s)){inNotice=false}continue}
      // 原因：「試題詳解」區沒被排除，解析的 1. 2. 會變成假題目，且答案列 1.(B) 2.(A)… 沒被讀取；進入答案區後只收這種純答案列，其餘照舊略過。
      // 原因：第 1 題的編號若在圖裡，「1.」之前的圖與文字原本因 ex 為空被丟掉；先放進編號 0 的暫存詳解，缺號切分時才有東西可切。
      if(/參考答案|試題詳解/.test(s)){inKey=true;cur=null;if(!ex)ex=pre={no:0,blocks:[],cuts:[],fresh:false};continue}
      if(inKey){
        if(/^(?:\d{1,3}\s*[.、．]?\s*[(（][A-Ha-h]{1,8}[)）]\s*)+$/.test(s.trim())){kl.push(s.replace(/[(（]([A-Ha-h]{1,8})[)）]/g,'$1'));continue}
        // 原因：答案列之後的「N. …」是每題的詳解。編號要依序（容許跳過 1~2 個）且不超過最後一題，避免把詳解裡的步驟編號當成新的一題。
        // 原因：詳解區「二、非選擇題」之後是非選擇題的參考答案（1. reach ; minutes…），不是第 N 題詳解；單獨收進 nrf，才不會併進第 42 題。
        if(/^[一二三四五六七八九十壹貳參肆伍]+\s*[、.．]\s*非選擇題/.test(s)){flushLead();inKN=true;nrc=null;continue}
        if(inKN){const r=s.match(/^(\d{1,3})\s*[.．、](?!\d)\s*([\s\S]*)$/);if(r){nrc={no:+r[1],blocks:r[2].trim()?[{t:'text',v:r[2].trim()}]:[]};nrf.push(nrc)}else if(nrc)push(nrc,s,false);continue}
        // 原因：OCR 會在題號前留雜訊（ˉ32.、_(ˉ)36.），認不出編號整題會併進前一題。
        const sk=s.replace(/^(?:_\(\u02C9\)|\u02C9)+/,'');
        const hm=sk.match(/^(\d{1,3})\s*[.．、](?!\d)\s*([\s\S]*)$/);
        if(hm&&!/^(?:\d{1,3}\s*[.、．:：)）\-—]?\s*[A-Ha-h]{1,8}\s*)+$/.test(s)&&+hm[1]>exLast&&+hm[1]<=exLast+3&&+hm[1]<=last){
          // 原因：前導內容只在「下一題是題組首題」時歸給它；其他情況原樣接回前一題，維持舊行為。
          const gs=ps.some(x=>x.from===+hm[1]),ld=L.blocks;L.blocks=[];
          if(ld.length&&!gs&&ex)ex.blocks.push(...ld);
          ex={no:+hm[1],blocks:[],cuts:[],fresh:false};if(ld.length&&gs)ex.lead=ld;exs.push(ex);exLast=ex.no;
          if(hm[2].trim())ex.blocks.push({t:'text',v:hm[2].trim()});
          continue;
        }
        if(ex){
          if(ex.closed&&ex.no>0)push(L,s,!f&&!/^(?:[(（](?:[A-Ha-h]|\d{1,2})[)）]|[A-Ha-h]\s*[.、．)）]|【)/.test(s));
          else if(ex.fresh){ex.blocks.push({t:'text',v:s});ex.fresh=false}
          else push(ex,s,!f&&!/^(?:[(（](?:[A-Ha-h]|\d{1,2})[)）]|[A-Ha-h]\s*[.、．)）]|【)/.test(s));
        }
        continue;
      }
      // 原因：非選擇題的 1. 2. 3. 以前被當成第二輪題號，last 被拉回 3，詳解編號判斷（<=last）從此只認得 1~3；進入該區段後改收進 nms，不再碰 cur／last。
