        if(b.ls.some(x=>/參考答案|試題詳解/.test(x)))continue;
        let r;
        if((r=s.match(/^[ⅠⅡⅢⅣⅤⅥⅦⅧⅨⅩ]+\s*[.．、]\s*(.*)$/))){nsec={t:r[1].trim(),ins:[]};nc=null;continue}
        if(/^說明[:：]?$/.test(s))continue;
        if(s[0]==='▲'){if(nsec)nsec.ins.push(s.slice(1).trim());nc=null;continue}
        if((r=s.match(/^(\d{1,3})\s*[.．、](?!\d)\s*([\s\S]*)$/))){nc={no:+r[1],sec:nsec?nsec.t:'',ins:nsec?nsec.ins:[],blocks:r[2].trim()?[{t:'text',v:r[2].trim()}]:[]};nms.push(nc);continue}
        if(nc)push(nc,s,false);else if(nsec&&nsec.ins.length&&!f)nsec.ins[nsec.ins.length-1]=jn(nsec.ins[nsec.ins.length-1],s);
