    }
    // 原因：詳解含 (D) 或來自 code 區塊，代表該題詳解已寫完；其後出現的未編號內容是下一題組的前導（文章翻譯、圖表），不該算在這一題。
    if(inKey&&ex&&ex.no>0&&!ex.closed&&(b.cz||/[(（]D[)）]/.test(ex.blocks.filter(x=>x.t==='text').map(x=>x.v).join('\n'))))ex.closed=true;
