  flushLead();
  const runs=[];let r=[];
  qs.forEach(q=>{if(r.length&&q.no<=r[r.length-1].no){runs.push(r);r=[]}r.push(q)});runs.push(r);
  const keep=runs.sort((a,b)=>b.length-a.length)[0]||[];
  // 原因：詳解編號被併進圖片（「5.」是圖的一部分）時 OCR 讀不到編號，缺號那題會被併進前一題。舊做法只認「換頁」且只處理缺 1 題，沒換頁就悄悄不切。
  // 現在：缺號處（含最前面缺、最後面缺、一次缺多題）以「圖片區塊的起點」為切點，因為編號消失在圖裡，圖就是那題詳解的開頭；與換頁位置重合的圖優先，沒有圖才退回換頁位置。
  // 兩者都不夠就不切，標記 gap 讓檢討頁明說；切出來的一律標記為推測（inf）。沒有任何詳解編號（exs 為空）時不推測。
  const mxNo=keep.length?keep[keep.length-1].no:0,all=exs.length?[pre,...exs]:[],fin=[];
  all.forEach((a,k)=>{
    const m=(all[k+1]?all[k+1].no:mxNo+1)-a.no-1,L=a.blocks.length;
    fin.push(a);
    if(m<1)return;
    const imgs=a.blocks.map((b,j)=>j>=(a.no?1:0)&&b.t==='img'&&!(j&&a.blocks[j-1].t==='img')?j:-1).filter(j=>j>=0),
