  const W=wrapBareLatex,wb=bl=>bl.map(b=>b.t==='text'?{...b,v:W(b.v.trim())}:b).filter(b=>b.t!=='text'||b.v);
  const key={};kh.forEach(h=>keyFromHtml(h,key));kl.forEach(l=>Object.assign(key,parseKey(l)));if(keyText)Object.assign(key,parseKey(keyText));
  const questions=keep.map(q=>{
    const{stem,opts}=splitOpts(q.blocks.filter(b=>b.t==='text').map(b=>b.v).join('\n'));
