    q.blocks.forEach(b=>{if(b.t!=='text')bl.push(b);else if(!done){done=1;if(stem)bl.push({t:'text',v:W(stem)})}});
    const r={no:q.no,pid:q.pid,blocks:bl,options:opts.map(o=>({...o,v:W(o.v)})),key:key[q.no]||''};
    const e=expOf[q.no],eb=e?wb([...(e.lead||[]),...e.blocks]):[];
    if(eb.length){r.exp=eb;if(e.inf)r.expInf=true;if(e.gap)r.expGap=e.gap;if(e.lead)r.expLead=true}
