        return {"removed": True}


# ---- 卡片引用文獻（同一張卡片可對同一份文獻引用多個位置，每個位置一列）----


@router.get("/cards/{card_id}/literature")
def list_card_literature(card_id: str, request: Request):
    with session(request, write=False) as conn:
        _card_must_exist(conn, card_id)
        rows = conn.execute(
            """SELECT cl.id, cl.literature_id, l.title, l.author, cl.locator
               FROM card_literature cl JOIN literature l ON l.id = cl.literature_id
               WHERE cl.card_id = ? ORDER BY l.title, cl.locator""",
            (card_id,),
        ).fetchall()
        return {"citations": [dict(r) for r in rows]}


@router.put("/cards/{card_id}/literature")
def put_card_literature(card_id: str, payload: CardLiteraturePut, request: Request):
    locator = payload.locator.strip()
    with session(request, write=True) as conn:
        _card_must_exist(conn, card_id)
        _literature(conn, payload.literature_id)
        row = conn.execute(
            "SELECT id FROM card_literature WHERE card_id = ? AND literature_id = ? AND locator = ?",
            (card_id, payload.literature_id, locator),
        ).fetchone()
        if row is not None:  # 同卡片、同文獻、同位置已存在：重送不重複建立
            return {
                "id": row["id"],
                "card_id": card_id,
                "literature_id": payload.literature_id,
                "locator": locator,
                "existed": True,
            }
        cid = new_id()
        conn.execute(
            "INSERT INTO card_literature (id, card_id, literature_id, locator, created_at) VALUES (?, ?, ?, ?, ?)",
            (cid, card_id, payload.literature_id, locator, utc_now()),
        )
        return {
            "id": cid,
            "card_id": card_id,
            "literature_id": payload.literature_id,
            "locator": locator,
            "existed": False,
        }


@router.patch("/literature-citations/{citation_id}")
def patch_literature_citation(citation_id: str, payload: LiteratureCitationPatch, request: Request):
    locator = payload.locator.strip()
    with session(request, write=True) as conn:
        row = conn.execute("SELECT * FROM card_literature WHERE id = ?", (citation_id,)).fetchone()
        if row is None:
            raise AppError(ErrorCode.NOT_FOUND, "引用不存在", {"citation_id": citation_id})
        dup = conn.execute(
            """SELECT 1 FROM card_literature
               WHERE card_id = ? AND literature_id = ? AND locator = ? AND id <> ?""",
            (row["card_id"], row["literature_id"], locator, citation_id),
        ).fetchone()
        if dup is not None:
            raise AppError(ErrorCode.VALIDATION_ERROR, "這張卡片已經有引用同一份文獻的相同位置")
        conn.execute("UPDATE card_literature SET locator = ? WHERE id = ?", (locator, citation_id))
        return {
            "id": citation_id,
            "card_id": row["card_id"],
            "literature_id": row["literature_id"],
            "locator": locator,
        }


@router.delete("/literature-citations/{citation_id}")
def delete_literature_citation(citation_id: str, request: Request):
    with session(request, write=True) as conn:
        cur = conn.execute("DELETE FROM card_literature WHERE id = ?", (citation_id,))
        if cur.rowcount == 0:
            raise AppError(ErrorCode.NOT_FOUND, "引用不存在", {"citation_id": citation_id})
        return {"removed": True}
