            </button>
            <button type="button" onClick={() => setReportOpen(true)}>
              📊 評估報告與候選池
            </button>
            <button type="button" onClick={() => setNotesOpen(true)} title="查看新增橋樑詞與句型的規則、評估方法與待處理清單">
