        ) : (
          <>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 6 }}>
              <label className="field-row" style={{ margin: 0 }}>
                <span className="muted" style={{ fontSize: 11 }}>角色 A（選填）：</span>
                <input
