              <label className="field-row" style={{ margin: 0 }}>
                <span className="muted" style={{ fontSize: 11 }}>角色 B（選填）：</span>
                <input
                  value={roleB}
                  onChange={(e) => setRoleB(e.target.value)}
                  placeholder="例：上斜方肌 / 剩餘掛單者"
                />
              </label>
              <label className="field-row" style={{ margin: 0 }}>
                <span className="muted" style={{ fontSize: 11 }}>結果（選填）：</span>
                <input
