                {PATTERN_FAMILIES.map((fam) => {
                  const list = patternsByFamily.get(fam) ?? [];
                  if (list.length === 0) return null;
                  return (
                    <optgroup key={fam} label={PATTERN_FAMILY_GUIDES[fam].name}>
