                {(patternsByFamily.get("none") ?? []).length > 0 && (
                  <optgroup label="未分類">
                    {(patternsByFamily.get("none") ?? []).map((p) => (
                      <option key={p.id} value={p.id}>
                        {p.label} → 【{p.bridge_name}】
