interface Props {
  card: CardDetail;
  tags: Tag[];
  onAssignBridgeTag(tagId: string, note?: string): Promise<void>;
  onSelectCard?(cardId: string): void;
  report(e: unknown, prefix?: string): void;
  info?(text: string): void;
